import java.util.*;

class Solution {
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        long count = 0;

        Map<Long, Long> prevResults = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            Map<Long, Long> currResults = new HashMap<>();

            if (nums[i] == k) {
                ++count;
            }
            currResults.put((long) nums[i], 1L);

            for (Map.Entry<Long, Long> entry : prevResults.entrySet()) {
                long val = entry.getKey();
                long freq = entry.getValue();

                long newAndResult = val & nums[i];
                if (newAndResult == k) {
                    count += freq;
                }

                currResults.put(newAndResult, currResults.getOrDefault(newAndResult, 0L) + freq);
            }

            prevResults = currResults;
        }

        return count;
    }
}

int prefixSums[100001][32];

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long counts = 0;
        int lower, upper, middle, length, AND, answer1, answer2;
        for (int i = 0; i != nums.size(); ++i) {
            for (int j = 0; j < 32; ++j) {
                prefixSums[i + 1][j] = prefixSums[i][j] + ((nums[i] >> j) & 1);
            }
        }
        for (int i = 0; i != nums.size(); ++i) {
            lower = i;
            upper = nums.size() - 1;
            answer1 = answer2 = -1;
            while (lower <= upper) {
                AND = 0;
                middle = (lower + upper) >> 1;
                length = middle - i + 1;
                for (int j = 0; j < 32; ++j) {
                    if (prefixSums[middle + 1][j] - prefixSums[i][j] == length) {
                        AND |= (1 << j);
                    }
                }
                if (AND <= k) {
                    answer1 = middle;
                    upper = middle - 1;
                }
                else {
                    lower = middle + 1;
                }
            }
            lower = i;
            upper = nums.size() - 1;
            while (lower <= upper) {
                AND = 0;
                middle = (lower + upper) >> 1;
                length = middle - i + 1;
                for (int j = 0; j < 32; ++j) {
                    if (prefixSums[middle + 1][j] - prefixSums[i][j] == length) {
                        AND |= (1 << j);
                    }
                }
                if (AND <= k - 1) {
                    answer2 = middle;
                    upper = middle - 1;
                }
                else {
                    lower = middle + 1;
                }
            }
            if (answer1 != -1) {
                if (answer2 == -1) {
                    counts += nums.size() - answer1;
                    //cout << nums.size() - answer1 << ' ';
                }
                else {
                    counts += answer2 - answer1;
                    //cout << answer2 - answer1 << "(" << answer1 << ' ' << answer2 << ") ";
                }
            }
        }
        //cout << '\n';
        return counts;
    }
};

