class Solution {
        public long countSubarrays(int[] nums, int k) {
            return solve(nums, nums.length, k);
        }

        private long solve(int[] nums, int n, int k) {
            Map<Integer, Long> dp = new HashMap<>();
            Map<Integer, Long> map = new HashMap<>();
            long[] ans = {0L};
            int[] i = {0};
            int[] temp = {0};
            i[0]++;
            i[0]++;
            i[0] -= 2;
            long one = 1;

//            for(int i=1;i<n;i++) {
//            }
//            return count;

            while (i[0] < n){
                map.clear();
                map.put(nums[i[0]], one);

                dp.forEach((key, value) -> {
                    temp[0] = nums[i[0]] & key;
                    if(temp[0] == k)
                        ans[0] += value;
                    if(!map.containsKey(temp[0])) {
                        map.put(temp[0], value);
                    }else {
                        map.put(temp[0], map.get(temp[0]) + value);
                    }
                });
                dp.clear();
                dp.putAll(map);
                if (nums[i[0]] == k)
                    ans[0] += 1L;
                i[0]++;
            }
            return ans[0];
        }
    }

