class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        vector<int> nums2=nums;
        for(int i=0;i<nums.size();++i)nums[i]&=k;
        vector<int> dp(n);
        for(int i=n-1;i>=0;--i){
            if(nums[i]==k){
                dp[i]=1;
                if(i+1<n)dp[i]+=dp[i+1];
            }
        }
        long long res=0;
        vector<int> index(30,n);
        for(int i=n-1;i>=0;--i){
            if(nums[i]==k){
                if(nums2[i]>k){
                    int maxi=i;
                    for(int j=0;j<30;++j){
                        if((1<<j)&k)continue;
                        if((1<<j)&nums2[i]){
                            maxi=max(maxi,index[j]);
                        }else{
                            index[j]=i;
                        }
                    }
                    if(maxi!=n&&maxi<=i+dp[i]-1)res+=dp[maxi];
                }else{
                    for(int j=0;j<30;++j){
                        if((1<<j)&nums2[i])continue;
                        index[j]=i;
                    }
                    res+=dp[i];        
                }
                // cout<<i<<" "<<res<<endl;
                continue;
            }
            // cout<<i<<" "<<res<<endl;
            for(int j=0;j<30;++j){
                if((1<<j)&nums2[i])continue;
                index[j]=i;
            }
            if(nums[i]<k)continue;
        }
        return res;
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public long countSubarrays(int[] numbers, int targetValue) {
        int arrayLength = numbers.length;
        long totalCount = 0;
        Map<Long, Long> previousBitwiseResults = new HashMap<>();

        for (int currentIndex = 0; currentIndex < arrayLength; ++currentIndex) {
            Map<Long, Long> currentBitwiseResults = new HashMap<>();

            if (numbers[currentIndex] == targetValue) {
                ++totalCount;
            }
            currentBitwiseResults.put((long)numbers[currentIndex], 1L);

            for (Map.Entry<Long, Long> entry : previousBitwiseResults.entrySet()) {
                long previousResult = entry.getKey();
                long frequency = entry.getValue();
                long newBitwiseAndResult = previousResult & numbers[currentIndex];

                if (newBitwiseAndResult == targetValue) {
                    totalCount += frequency;
                }
                currentBitwiseResults.put(newBitwiseAndResult, 
                    currentBitwiseResults.getOrDefault(newBitwiseAndResult, 0L) + frequency);
            }

            previousBitwiseResults = currentBitwiseResults;
        }

        return totalCount;
    }
}

class Solution:
    def countSubarrays(self, a: List[int], k: int) -> int:
        n=len(a)
        ans=0
        d=defaultdict(int)
        for i in range(n):
            td=defaultdict(int)
            if a[i]==k:
                ans+=1
            td[a[i]]=1
            for key in d:
                an=key&a[i]
                if an==k:
                    ans+=d[key]
                td[an]+=d[key]
            d=td
        return ans

