public class Solution {
    public long CountSubarrays(int[] arr, int tgt)
    {
        int n = arr.Length;
        long count = 0;
        var prev = new Dictionary<long, long>();

        for (int i = 0; i < n; ++i)
        {
            var curr = new Dictionary<long, long>();
            if (arr[i] == tgt)
            {
                ++count;
            }

            curr[arr[i]] = 1;

            foreach (var entry in prev)
            {
                long val = entry.Key;
                long freq = entry.Value;
                long newAnd = val & arr[i];
                if (newAnd == tgt)
                {
                    count += freq;
                }
                if (curr.ContainsKey(newAnd))
                {
                    curr[newAnd] += freq;
                }
                else
                {
                    curr[newAnd] = freq;
                }
            }

            prev = curr;
        }

        return count;
    }
}

static constexpr unsigned bits = 31;
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        const unsigned n = nums.size();
        vector<array<unsigned, bits>> cntbits(n + 1);
        array<unsigned, bits> cnt {};
        for (unsigned i = 0; i < n; ++i) {
            auto num = nums[i];
            for (unsigned bit = 0; num; ++bit, num >>= 1)
                cnt[bit] += num & 1;
            cntbits[i + 1] = cnt;
        }
        auto andsum = [&](auto l, auto r) { // nums[l] & ... & nums[r]
            int ret = 0;
            for (unsigned bit = 0, bm = 1; bit < bits; ++bit, bm <<= 1)
                if (cntbits[r + 1][bit] - cntbits[l][bit] == r - l + 1)
                    ret |= bm;
            return ret;
        };
        auto countbits = [k](auto v) {
            unsigned missing = 0;
            unsigned extra = 0;
            for (unsigned i = 0, mask = 1; i < bits; ++i, mask <<= 1) {
                if ((v & mask) && !(k & mask))
                    ++extra;
                if (!(v & mask) && (k & mask))
                    ++missing;
            }
            return pair { missing, extra };
        };
        long long ret = 0;
        for (unsigned i = 0; i < n; ++i) {
            //assert(andsum(i, i) == nums[i]);
            {
                auto [miss, ex] = countbits(nums[i]);
                if (miss)
                    continue;
            }
            {
                auto [miss, ex] = countbits(andsum(0, i));
                if (ex)
                    continue;
            }
            unsigned a;
            // look for first index such that andsum(a, i) does not have missing bits
            {
                unsigned lo = 0;
                unsigned hi = i;
                while(lo < hi) {
                    unsigned mid = lo + (hi - lo)/2;
                    auto s = andsum(mid, i);
                    auto [miss, ex] = countbits(s);
                    if (miss)
                        lo = mid + 1;
                    else
                        hi = mid;
                }
                a = lo;
            }
            {
                auto [miss, ex] = countbits(andsum(a, i));
                if (ex)
                    continue;
            }
            // look for last index that has no extra bits
            unsigned b;
            {
                unsigned lo = a;
                unsigned hi = i;
                while(lo < hi) {
                    unsigned mid = lo + (hi - lo + 1)/2;
                    auto s = andsum(mid, i);
                    auto [miss, ex] = countbits(s);
                    if (ex)
                        hi = mid - 1;
                    else
                        lo = mid;
                }
                b = lo;
            }
            ret += b - a + 1;
        }
        return ret;        
    }
};

