class Solution {
public:
  int rangeand(vector<int> &bits,int len){
    int ans=0;
    for(int b=0;b<31;b++){
        if(bits[b]==len) ans+=(1<<b);
    }
    return ans;
  }
    long long atleastk(vector<int> &nums,int k){
        vector<int> bits(32,0);
        long long ans=0;
        int i=0;
        for(int j=0;j<nums.size();j++){
            for(int b=0;b<31;b++){
                if((1<<b)&nums[j]) bits[b]++;
            }
            while(i<=j&&rangeand(bits,j-i+1)<k){
                for(int b=0;b<31;b++){
                if((1<<b)&nums[i]) bits[b]--;
            }
                i++;
            }
            ans=ans+(j-i+1);
        }
        return ans;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        return atleastk(nums,k)-atleastk(nums,k+1);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        vector<int>use(n);
        int l=-1;
        for(int i=0;i<n;i++){
            int curr=(nums[i]&k);
            if(curr<k)l=i;
            use[i]=l;
        }
        vector<vector<int>>v(33,vector<int>(n+1));
        for(int bit=0;bit<31;bit++){
            int num=(1<<bit);
            int l=-1;
            for(int i=0;i<n;i++){
                if(!(nums[i]&num))l=i;
                v[bit][i]=l;
            }
        }
        long long ans=0;
        for(int i=0;i<n;i++){
            if(use[i]==i)continue;
            int num=(k^nums[i]);
            int y=0;
            int idx=i;
            while(num>0){
                if((num&1))idx=min(idx,v[y][i]);
                num>>=1;
                y++;
            }
            int sz=(idx-use[i]);
            sz=max(sz,0);
            ans=(long long)ans+sz;
        }
        return ans;
    }
};

