    int[][] makeGraph(int N, int M) {

        int[][] G = new int[N][];

        int[] p = new int[N];

        for (int i = 0; i < M; i++) {

            p[from[i]]++;

            p[to[i]]++;

        }

        for (int i = 0; i < N; i++)
            G[i] = new int[p[i]];

        for (int i = 0; i < M; i++) {

            G[from[i]][--p[from[i]]] = to[i];

            G[to[i]][--p[to[i]]] = from[i];

        }

