    class FenwickTree {

        public int[] tree;

        public int size;

        public FenwickTree(int size) {

            this.size = size;

            tree = new int[size + 5];

        }

        public void add(int i, int v) {

            while (i <= size) {

                tree[i] += v;

                i += i & -i;

            }

        }

        public int find(int i) {

            int res = 0;

            while (i >= 1) {

                res += tree[i];

                i -= i & -i;

            }

            return res;

        }

        public int find(int l, int r) {

            return find(r) - find(l - 1);

        }

    }

    class STLazy {

        int leftmost;

        int rightmost;

        STLazy lchild;

        STLazy rchild;

        int sum;

        public STLazy(int leftmost, int rightmost, int[] a) {

            this.leftmost = leftmost;

            this.rightmost = rightmost;

            if (leftmost == rightmost) {

                // leaf

                sum = a[leftmost];

            } else {

                // 2 children

                int mid = (leftmost + rightmost) / 2;

                // (l,mid) (mid+1,r)

                lchild = new STLazy(leftmost, mid, a);

                rchild = new STLazy(mid + 1, rightmost, a);

                recalc();

            }

        }

        public void recalc() {

            if (leftmost == rightmost)
                return;

            sum = Math.max(lchild.sum, rchild.sum);

        }

        public void update(int index, int newVal) {

            if (leftmost == rightmost) {

                // leaf;

                sum += newVal;

            } else {

                // 2 children

                if (index <= lchild.rightmost)
                    lchild.update(index, newVal);

                else
                    rchild.update(index, newVal);

                recalc();

            }

        }

        public int query(int l, int r) {

            // entirely disjoint

            if (l > rightmost || r < leftmost)
                return 0;

            // covers us

            if (l <= leftmost && r >= rightmost)
                return sum;

            // we don't know

            return Math.max(lchild.query(l, r), rchild.query(l, r));

        }

    }

