class Solution {
#define pb push_back
public:
    int seg[400005];
    vector<int> v;

    void build(int id, int l, int r) {
        if (l == r) {
            seg[id] = v[l];
            return;
        }
        int mid = (l + r) >> 1;
        build(id << 1, l, mid);
        build(id << 1 | 1, mid+1, r);
        seg[id] = seg[id<<1] & seg[id<<1 | 1];
    }

    int ask(int id, int l, int r, int L, int R) {
        //cout << "l = " << l << " r = " << r << endl;
        if (l > R || r < L) return -1;
        if (L <= l && r <= R) {
            return seg[id];
        } 
        int mid = (l + r) >> 1;
        return (ask(id<<1, l, mid, L, R) & ask(id<<1|1, mid+1, r, L, R));
    }

    bool check(int a, int k) {
        for (int i = 0; i < 32; i++) if ((k>>i) & 1) {
            if (!((a>>i)&1)) return true;
        }
        return false;
    }

    bool check2(int a, int k) {
        for (int i = 0; i < 32; i++) if ((k>>i) & 1) {
            if (!((a>>i)&1)) return false;
        }
        if (a > k) return true;
        return false;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = (int)nums.size();

        long long ans = 0;

        v.pb(0);
        for (int i:nums) v.pb(i);

        build(1, 1, n);

        for (int i = 1; i <= n; i++) {
            //cout << "i = " << i << endl;
            int l = i+1, r = n+1;
            while (l < r) {
                int mid = (l + r) >> 1;
                if (check(ask(1, 1, n, i, mid), k)) {
                    r = mid;
                } else {
                    l = mid + 1;
                }
            }
            int s = l - 1;
            //cout << "s = " << s << endl;
            l = i+1; r = n+1;
            while (l < r) {
                int mid = (l + r) >> 1;
                //cout << "mid = " << mid << " ask = " << ask(1, 1, n, i, mid) << endl;
                if (check2(ask(1, 1, n, i, mid), k)) {
                    l = mid + 1;
                } else {
                    r = mid;
                }
            }
            int f = l;
            //cout << "f = " << f << endl;
            ans += max(0, s - f + 1);
            if (v[i] == k) ans++;
        }
        return ans;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& array, int target) {
        int size = array.size();
        long long total = 0;
        unordered_map<long long, long long> previousResults;
        for (int index = 0; index < size; ++index) {
            unordered_map<long long, long long> currentResults; 
            if (array[index] == target) {
                ++total;
            }
            currentResults[array[index]] = 1;
            for (auto& [value, frequency] : previousResults) {
                long long newAndResult = value & array[index];
                if (newAndResult == target) {
                    total += frequency;
                }
                currentResults[newAndResult] += frequency;
            }

            previousResults = currentResults;
        }
        return total;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int target) {
        long long i, j, k, n = nums.size(), ans = 0, mi, ma;
        deque<int> v[32];
        for(i=0;i<n;i++){
            for(j=0;j<31;j++){
                if((nums[i] & (1 << j)) == 0)  v[j].push_back(i);
            }
        }
        for(j=0;j<31;j++)   v[j].push_back(n);

        for(i=0;i<n;i++){
            mi = n, ma = -1;
            for(j=0;j<31;j++){
                if(target & (1 << j)){
                    mi = min((int)mi, v[j].front());
                    if(v[j].front() == i)   v[j].pop_front();
                }
                else{
                    ma = max((int)ma, v[j].front());
                    if(v[j].front() == i)   v[j].pop_front();
                }
            }
            if(mi > ma)  ans += (mi - ma);
        }
        return ans;
    }
};

#define ll long long int
class Solution {
public:
    void updateBits(vector<int> &store, int num) {
        int pos = 31;
        while(num) {
            store[pos] += (num & 1);
            num >>= 1;
            pos--;
        }
    }

    void updateNegativeBits(vector<int> &store, int num) {
        int pos = 31;
        while(num) {
            store[pos] = max(0, store[pos] - (num & 1));
            num >>= 1;
            pos--;
        }
    }

    bool isValid(int k, vector<int> &store) {
        int pos = 31;
        while(k) {
            if((k & 1) && store[pos] == 0)
                return false;
            k >>= 1;
            pos--;
        }
        return true;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        ll ans = 0;
        unordered_map<ll, ll> prev;
        for (int i = 0; i < n; i++) {
            unordered_map<ll, ll> next; 
            if (nums[i] == k) ans++;
            next[nums[i]] = 1;

            for (auto it : prev) {
                if ((it.first & nums[i]) == k) ans += it.second;
                next[it.first & nums[i]] += it.second;
            }
            prev = next;
        }
        return ans;
    }
};

