class Solution {
public:
    long long fun(vector<int>& v,int l,int r,int k)
    {
        map<int,int> fr;
        long long rt=l,ans=0;
        for(int i=0;i<31;i++)if(v[l]&(1<<i))fr[i]++;
        for(int in=l;in<=r;in++)
        {
            if(rt<in)
            {
                // cout<<"hr"<<endl;
                rt=in;
                for(int i=0;i<31;i++)if(v[rt]&(1<<i))fr[i]++;
            }
            while(1)
            {
                int ad=v[in];
                for(int i=0;i<31;i++)
                {
                    if(fr[i]<rt-in+1 && (ad&(1<<i)))ad-=(1<<i);
                }
                // if(in==1)cout<<"lyo"<<ad<<endl;
                if(ad!=k && rt<=r)
                {
                    rt++;
                    if(rt<=r)for(int i=0;i<31;i++)if(v[rt]&(1<<i))fr[i]++;
                }
                else break;
            }
            if(rt>r)break;
            // cout<<in<<" "<<rt<<endl;
            ans+=r-rt+1;
            for(int i=0;i<31;i++)if(v[in]&(1<<i))fr[i]--;
        }
        return ans;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        long long lst=0,ans=0;
        for(int i=0;i<n;i++)
        {
            for(int bt=0;bt<31;bt++)
            {
                if(!(nums[i]&(1<<bt)))
                {
                    if((k&(1<<bt)))
                    {
                        // cout<<i<<" "<<lst<<endl;   
                        if(lst<i)ans+=fun(nums,lst,i-1,k);
                        lst=i+1;
                        break;
                    }
                }
                if(bt==30 && i==n-1)ans+=fun(nums,lst,i,k);
            }
        }
        return ans;
    }
};

class Solution {
    public long countSubarrays(int[] nums, int k) {
        long count = 0;

        Map<Long, Long> a = new HashMap<>();

        for (int num : nums) {
            Map<Long, Long> b = new HashMap<>();

            b.put((long) num, b.getOrDefault((long) num, 0L) + 1);
            for (long key : a.keySet()) {
                long newKey = key & num;
                b.put(newKey, b.getOrDefault(newKey, 0L) + a.get(key));
            }

            if (b.containsKey((long) k)) {
                count += b.get((long) k);
            }

            a = b;
        }

        return count;
    }
}

class Solution {
public:

    int comp(vector<int> &arr, vector<int> &prev, int len, vector<int>& tar){
        for(int i=0; i<32; i++){
            if(tar[i] && arr[i]-prev[i] < len){
                return -1;
            }else if(tar[i] == 0 && arr[i]-prev[i] == len){
                return 1;
            }
        }
        return 0;
    }

    int g1(vector<vector<int>>&arr, vector<int> &tar, int ind){
        int l = ind, h = arr.size()-1, ans = -1;

        vector<int> prev = ind == 0 ? vector<int>(32, 0) : arr[ind-1];



        while(l <= h){
            int mid = l + (h-l)/2;
            int len = mid - ind +1;

            int ret = comp(arr[mid], prev, len, tar);




            if(ret == -1){
                h = mid-1;
            }else if(ret == 1){
                l = mid+1;
            }else{
                ans = mid;
                h = mid-1;
            }
        }

        return ans;
    }

    int g2(vector<vector<int>>&arr, vector<int> &tar, int ind){
        int l = ind, h = arr.size()-1, ans = -1;

        vector<int> prev = ind == 0 ? vector<int>(32, 0) : arr[ind-1];

        while(l <= h){
            int mid = l + (h-l)/2;
            int len = mid - ind +1;

            int ret = comp(arr[mid], prev, len, tar);

            // if(ind == 1){
            //     cout << l << " " << h << " " << ret << " " << mid << endl;
            // }


            if(ret == -1){
                h = mid-1;
            }else if(ret == 1){
                l = mid+1;
            }else{
                ans = mid;
                l = mid+1;
            }
        }

        return ans;
    }


    long long countSubarrays(vector<int>& nums, int k) {
        int N = nums.size();
        vector<vector<int>> arr(N, vector<int>(32, 0));
        vector<int>tar(32, 0);


        for(int i = 0; i<N; i++){
            for(int j = 0; j<32; j++){
                if(nums[i] & (1 << j)){
                    arr[i][j] = i == 0 ? 1 : arr[i-1][j] + 1;
                }else{
                    arr[i][j] = i==0 ? 0 : arr[i-1][j];
                }
            }
        }

        for(int i = 0; i<32; i++){
            tar[i] = k & (1 << i) ? 1 : 0;
        }

//          for(int j = 0; j<32; j++){
//         for(int i = 0; i<N; i++){

//                 cout << arr[i][j] << " ";
//             }

//             cout << endl;
//         }

        long long ans = 0;
        for(int i = 0; i<N; i++){
            int lowEnd = g1(arr, tar, i);
            int highEnd = g2(arr, tar, i);


            // cout << i << " " << lowEnd << " " << highEnd << endl;

            if(highEnd != -1 && lowEnd != -1){
                ans += highEnd - lowEnd + 1;
            }
        }

        return ans;
    }
};

