class Solution {
public:
    vector<vector<int>> bit;

    void make(vector<int>& ar)
    {
        int n = log2(ar.size())+1;
        bit.assign(n, vector<int>(ar.size(), 0));

        for(int i=0;i<ar.size();++i)
            bit[0][i]=ar[i];

        for(int i=1;i<n;++i)
        {
            for(int j=(1<<i)-1;j<ar.size();++j)
            {
                bit[i][j]=bit[i-1][j]&bit[i-1][j-(1<<(i-1))];
            }
        }
    }

    int get(int l, int r)
    {
        if(l==r)
            return bit[0][l];
        int x = log2(r-l+1);
        return bit[x][r]&bit[x][l+(1<<x)-1];       

    }

    long long countSubarrays(vector<int>& ar, int k) {
        long ans = 0;
        make(ar);

        for(int i=0;i<ar.size();++i)
        {
            int s = 0, e = i, lef=-1, rig=-1;
            //cout<<s<<" "<<e<<endl;
            while(s<=e)
            {
                int mid = (s+e)>>1;
                int x = get(mid, i);
                if(x==k)
                    lef=mid, e = mid-1;
                else if(x<k)
                    s = mid+1;
                else
                    e = mid-1;
            }

            s=0, e=i;
            while(s<=e)
            {
                int mid = (s+e)>>1;
                int x = get(mid, i);
                if(x==k)
                    rig=mid, s = mid+1;
                else if(x<k)
                    s = mid+1;
                else
                    e = mid-1;
            }

            //cout<<i<<" "<<rig-lef+1<<endl;

            if(lef!=-1)
                ans+=(rig-lef+1);
        }
        //cout<<endl;

        return ans;
    }
};

