class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans=0;
        int n=nums.size();
        vector<vector<int>> dp(31, vector<int> (n+1, 0));
        for(int i=0; i<n; i++)
        {
            for(int j=0; j<31; j++)
            {
                dp[j][i+1]=dp[j][i]+((nums[i]>>j)&1);
            }
        }

        int l=0;
        int r=0;
        while(l<n)
        {
            // cout<<l<<" "<<r<<" = "<<ans<<endl;

            int s=-1;
            while(r<n && (nums[r]&k)>=k) 
            {
                // cout<<"  r - "<<r<<endl;
                if(s==-1)
                {
                    int andval=0;
                    for(int j=0; j<31; j++)
                    {
                        if(dp[j][r+1]-dp[j][l]==r+1-l) andval^=(1<<j);
                    }
                    if(andval==k) s=r;
                }

                ++r;
            }
            if(s!=-1) ans+=r-s;
            else
            {
                l=r=l+1;
                continue;
            }
            // cout<<"  "<<l<<" - "<<s<<" - "<<r<<endl;
            ++l;

            while(l<r)
            {
                s=max(s, l);
                while(s<r)
                {
                    int andval=0;
                    for(int j=0; j<31; j++)
                    {
                        // cout<<"    j = "<<j<<" - "<<dp[j][s+1]<<", "<<dp[j][l]<<endl;
                        if(dp[j][s+1]-dp[j][l]==s+1-l) andval|=(1<<j);
                    }
                    // cout<<"    "<<andval<<endl;
                    if(andval==k) break;
                    ++s;
                }
                // cout<<"  "<<l<<" - "<<s<<" - "<<r<<endl;
                if(s==r)
                {
                    l=r;
                    break;
                }
                ans+=r-s;
                ++l;
            }
        }

        return ans;
    }
