class SegmentTree {
public:
    SegmentTree(const vector<int>& arr) {
        n = arr.size();
        tree.resize(4 * n);
        build(arr, 0, 0, n - 1);
    }

    int query(int l, int r) {
        return _query(0, 0, n - 1, l, r);
    }

private:
    int n;
    vector<int> tree;

    void build(const vector<int>& arr, int node, int start, int end) {
        if (start == end) {
            tree[node] = arr[start];
        } else {
            int mid = start + (end - start) / 2;
            build(arr, 2 * node + 1, start, mid);
            build(arr, 2 * node + 2, mid + 1, end);
            tree[node] = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }

    int _query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) {
            return INT_MAX;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        int mid = start + (end - start) / 2;
        int p1 = _query(2 * node + 1, start, mid, l, r);
        int p2 = _query(2 * node + 2, mid + 1, end, l, r);
        return p1 & p2;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long cnt = 0;
        SegmentTree st(nums);
        for (int i = 0; i < nums.size(); ++i) {
            int fo = INT_MAX;
            int lo = INT_MIN;
            int l = i;
            int r = nums.size() - 1;

            // Find the first occurrence (fo) where the AND is k
            while (l <= r) {
                int mid = l + (r - l) / 2;
                int a = st.query(i, mid);
                if (a == k) {
                    fo = mid;
                    r = mid - 1;
                } else if (a > k) {
                    l = mid + 1;
                } else {
                    r = mid - 1;
                }
            }

            l = i;
            r = nums.size() - 1;

            // Find the last occurrence (lo) where the AND is k
            while (l <= r) {
                int mid = l + (r - l) / 2;
                int a = st.query(i, mid);
                if (a == k) {
                    lo = mid;
                    l = mid + 1;
                }
                if (a < k) {
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }

            // If there is a valid range, count the number of subarrays
            if (fo != INT_MAX) {
                cnt += static_cast<long long>(lo - fo + 1);
            }
        }
        return cnt;
    }
};

