    unordered_map<long long, long long> andFreq;

    for (long long i = 0; i < n; ++i) {
        unordered_map<long long, long long> newAndFreq;
        if (nums[i] == k) count++; // Single element subarray

        for (auto &entry : andFreq) {
            long long newAnd = entry.first & nums[i];
            if (newAnd == k) count += entry.second;
            newAndFreq[newAnd] += entry.second;
        }

        newAndFreq[nums[i]]++; // Add the current element itself
        andFreq = newAndFreq;
    }

    return count;
    }
};

class Solution {
    public long countSubarrays(int[] nums, int k) {

       int n = nums.length;
        long count = 0;

        HashMap<Long, Long> prev = new HashMap<>();

        for (int i = 0; i < n; i++) {

            HashMap<Long, Long> curr = new HashMap<>();

            if (nums[i] == k) {
                count++;
            }
            curr.put((long) nums[i], 1L); 

            for (Map.Entry<Long, Long> entry : prev.entrySet()) {
                long val = entry.getKey();
                long freq = entry.getValue();
                long newAndResult = val & nums[i];
                if (newAndResult == k) {
                    count += freq;
                }
                curr.put(newAndResult, curr.getOrDefault(newAndResult, 0L) + freq);
            }

            prev = curr;
        }

        return count;
    }
}

class Solution {
public:
    long long countSubarrays(vector<int>& array, int target) {
        int size = array.size();
        long long total = 0;
        unordered_map<long long, long long> currentResults; 
        for (int index = 0; index < size; ++index) {
            unordered_map<long long, long long> newResults;
            if (array[index] == target) {
                ++total;
            }
            newResults[array[index]] = 1;
            for (auto& [value, frequency] : currentResults) {
                long long newAndResult = value & array[index];
                if (newAndResult == target) {
                    total += frequency;
                }
                newResults[newAndResult] += frequency;
            }

            currentResults = newResults;
        }
        return total;
    }
};

