class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size(),sq = sqrt(n), lastIndex = (n-1)/sq+1;
        vector<int> isKAndable(n);

        for(int i=0;i<n;i++) {
            if((nums[i]&k)==k) {
                isKAndable[i]=1;
            } else {
                isKAndable[i]=0;
            }
        }
        isKAndable[n-1] = isKAndable[n-1]==1?n-1:-1;
        for(int i=n-2;i>=0;i--) {
            if(isKAndable[i]==0) {
                isKAndable[i] = -1;
                continue;
            }
            if(isKAndable[i+1] == -1) {
                isKAndable[i] = i;
            } else {
                isKAndable[i] = isKAndable[i+1];
            }
        }

        vector<int> decom(lastIndex, -1);

        for(int i=0;i<n;i++) {
            int ind = i/sq;
            if(decom[ind]==-1) {
                decom[ind] = nums[i];
            } else {
                decom[ind] = decom[ind]&nums[i];
            }
        }
        long long int ans = 0;
        for(int i=0;i<n;i++) {
            int startIndex=-1, endIndex=-1;

            int ind = i/sq;
            int curr = nums[i];
            for(int j=i;(j<n) && (j<((ind+1)*sq));j++) {
                curr = curr&nums[j];
                if(curr == k) {
                    if(startIndex == -1) {
                        startIndex = j;
                        break;
                    }
                }
                if(curr<k) {
                    break;
                }
            }

            if(startIndex != -1) {
                endIndex = isKAndable[startIndex];
                ans+=(endIndex-startIndex+1);
            // cout<<i<<" a "<<ans<<' '<<startIndex<<' '<<endIndex<<' '<<curr<<endl;
                continue;
            }


            if(curr<k) {
                continue;
            }

            ind++;
            for(;ind<lastIndex;ind++) {
                if((curr&decom[ind])<=k) {
                    break;
                }
                curr = curr&decom[ind];
            }

            for(int j=ind*sq;j<n&&j<((ind+1)*sq);j++) {
                if((curr&nums[j])==k) {
                    startIndex = j;
                    break;
                }
                curr = curr&nums[j];
            }


            if(curr<k) {
                continue;
            }
            if(startIndex != -1) {
                endIndex = isKAndable[startIndex];
                ans+=(endIndex-startIndex+1);

            // cout<<i<<" b "<<ans<<' '<<startIndex<<' '<<endIndex<<' '<<curr<<endl;
                continue;
            }
        }
        return ans;
    }
};

