class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        vector<vector<int>> pre(n+1, vector<int> (32, 0));
        for(int i=0;i<n;i++){
            for(int j=0;j<32;j++){
                if(((nums[i]>>j)&1) != 0){
                    pre[i+1][j] = 1;
                }
            }
        }
        for(int i=1;i<=n;i++){
            for(int j=0;j<32;j++){
                pre[i][j] += pre[i-1][j];
            }
        }

        long long ans=0;
        for(int i=1; i<=n; i++){
            int low=i, high=n, curr=-1;

            // max where can get k
            while(low<=high){
                int mid = (low+high)/2;

                int len = mid-i+1;
                bool f=1,f1=1;
                for(int j=0; j<31; j++){
                    int x=pre[mid][j] - pre[i-1][j];
                    if((k&(1<<j)) != 0){
                        if(x!=len)
                            f1=false;
                    }else{
                        if(x==len)
                            f=false;
                    }
                }

                if(f1){
                    curr=mid;
                    low=mid+1;
                }else{
                    high=mid-1;
                }
            }

            int curr1 = curr;

            // min where can get k
            low=i, high=curr, curr=-1;

            while(low<=high){
                int mid = (low+high)/2;

                int len = mid-i+1;
                bool f=1, f1=1;
                for(int j=0; j<31; j++){
                    int x=pre[mid][j] - pre[i-1][j];
                    if((k&(1<<j)) != 0){
                        if(x!=len)
                            f1=false;
                    }else{
                        if(x==len)
                            f=false;
                    }
                }

                if(f){
                    curr=mid;
                    high=mid-1;
                }else{
                    low=mid+1;
                }
            }

            if(curr!=-1)
                ans += curr1-curr+1;
        }

        return ans;
    }
};

