#define ll int
class SegmentTree {
public:
    vector<int> tree;
    ll n;
    SegmentTree(vector<ll>& arr)
    {
        n = arr.size();
        tree.resize(4 * n);
        build(arr, 0, 0, n - 1);
    }

    void build(vector<ll>& arr, ll node, ll start,
               ll end)
    {
        if (start == end) {
            tree[node] = arr[start];
        }
        else {
            ll mid = (start + end) / 2;
            build(arr, 2 * node + 1, start, mid);
            build(arr, 2 * node + 2, mid + 1, end);
            tree[node] = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }

    ll query(ll l, ll r)
    {
        return query(0, 0, n - 1, l, r);
    }

    ll query(ll node, ll start, ll end, ll l, ll r)
    {
        if (r < start || end < l) {
            return INT_MAX;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        ll mid = (start + end) / 2;
        ll p1 = query(2 * node + 1, start, mid, l, r);
        ll p2 = query(2 * node + 2, mid + 1, end, l, r);

        return p1 & p2;
    }
};
class Solution {
public:
    long long solveK(vector<ll>& nums, ll k,SegmentTree& tr){
        int n = nums.size();
        int i=0,j=0;
        long long ans = 0;
        while(j<n){
            while(i<=j && tr.query(i,j)<=k){
                ans+=n-j;
                i++;
            }
            j++;
        }
        return ans;
    }
    long long countSubarrays(vector<ll>& nums, ll k) {
        int n = nums.size();
        SegmentTree tr(nums);
        return solveK(nums,k,tr) - solveK(nums,k-1,tr);
    }
};

class Solution {

    public long Solve(int s, int e, int [][] prefix, int k){
        int ptr=s;
        int st = s;
        long rem = 0l;
        while(ptr<e){
            boolean found = false;
            int gap = ptr-st+1;
            for(int j=0;j<31;j++){
                if(((1<<j) & k) != 0) continue;
                int freq = prefix[ptr][j] - (st==0?0:prefix[st-1][j]);

                if(freq == gap) {
                    ptr++;
                    found = true;
                    break;
                }
            }

            if(!found){
                st++;
            } else {
                rem += gap;
            }
        }
        return rem;
    }
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int [][] prefix = new int [n][31];
        long ans = 0l;
        for(int i=0;i<n;i++){
            for(int j=0;j<31;j++){
                if(((1<<j)&nums[i]) != 0){
                    prefix[i][j]=1+(i==0?0:prefix[i-1][j]);
                } else {
                    prefix[i][j] = (i==0?0:prefix[i-1][j]);
                }
            }
        }

        for(int i=0;i<n;i++){
            if((nums[i]&k) != k){
                continue;
            }
            int ptr=i;
            while(ptr < n){
                if((nums[ptr]&k)==k){
                    ptr++;
                } else {
                    break;
                }
            }
            int gap = ptr-i;
            ans += (gap*(gap+1l))/2l;
            int x=i;

            ans -= Solve(i, ptr, prefix, k);
            i=ptr-1;
        }

        return ans;
    }
}

