class Solution {
public:
    long long countSubarrays(vector<int>& ns, int k) {
        int n = ns.size();
        long long ct = 0;
        unordered_map<int, int> pc;

        for (int i = 0; i < n; ++i) {
            unordered_map<int, int> cc;
            ct += (ns[i] == k ? 1 : 0);
            cc[ns[i]] = 1;

            updateCounts(pc, cc, ns[i], k, ct);

            pc = cc;
        }

        return ct;
    }

private:
    void updateCounts(unordered_map<int, int>& pc, unordered_map<int, int>& cc, int val, int k, long long& ct) {
        auto it = pc.begin();
        while (it != pc.end()) {
            int na = it->first & val;
            ct += (na == k ? it->second : 0);
            cc[na] = cc.find(na) != cc.end() ? cc[na] + it->second : it->second;
            ++it;
        }
    }
};

