    const int N = 1e5 + 1;
class Solution {
public:

    int f[N * 4];

    void bulid(vector<int>& nums,int k,int l,int r){
        if(l == r){
            f[k] = nums[l-1];
            return;
        }
        int mid = (l + r) >> 1;
        bulid(nums,k << 1, l, mid);
        bulid(nums,(k << 1) + 1, mid + 1, r);
        f[k] = f[k << 1] & f[(k << 1) + 1];
    }

    int get(int k,int l,int r,int left,int right){
        if(l == left && r == right){
            return f[k];
        }
        int mid = (l + r) >> 1;
        if(right <= mid)return get(k << 1, l, mid, left, right);
        if(left > mid)return get((k << 1) + 1, mid + 1, r, left, right);
        return get(k << 1,l,mid,left, mid) & get((k << 1) + 1, mid + 1, r, mid + 1,right);
    }


    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        bulid(nums,1,1, n);
        long long ans = 0;
        for(int i = 1;i <= n;++i){
            int l = i,r = n;
            while(l <= r){
                int mid = (l + r) >> 1;
                int num = get(1,1,n,i, mid);
                if(num <= k){
                    r = mid - 1;
                }
                else{
                    l = mid + 1;
                }
            }
            ans -= l;
            l = i,r = n;

            while(l <= r){
                int mid = (l + r) >> 1;
                int num = get(1,1,n,i, mid);
                if(num < k){
                    r = mid - 1;
                }
                else{
                    l = mid + 1;
                }
            }
            ans += l;
        }
        cout << '\n';
        return ans;
    }
};

