class SegmentTree {
    vector<int> tree;
    int n;

public:
    SegmentTree(int n, vector<int> &v) {
        this->n = n;
        tree.resize(4 * n);
        build(v, 0, n - 1, 0);
    }

    void build(vector<int> &v, int start, int end, int node) {
        if (start == end) {
            tree[node] = v[start];
            return;
        }
        int mid = (start + end) / 2;
        build(v, start, mid, 2 * node + 1);
        build(v, mid + 1, end, 2 * node + 2);
        tree[node] = merge(tree[2 * node + 1], tree[2 * node + 2]);
    }

    int merge(int node1, int node2) {
        return node1 & node2;
    }

    int query(int left, int right) {
        return Query(left, right, 0, n - 1, 0);
    }

    int Query(int left, int right, int start, int end, int node) {
        if (left <= start && right >= end) {
            return tree[node];
        }
        if (left > end || right < start) {
            return INT_MAX; 
        }
        int mid = (start + end) / 2;
        int ans1 = Query(left, right, start, mid, 2 * node + 1);
        int ans2 = Query(left, right, mid + 1, end, 2 * node + 2);
        return merge(ans1, ans2);
    }


};
class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        SegmentTree st(n, nums);
        long long ans = 0;

        for (int i = 0; i < n; ++i) {
            int low = i, high = n - 1;
            int lower_bound = -1, upper_bound = -1;


            while (low <= high) {
                int mid = (low + high) / 2;
                if (st.query(i, mid) == k) {
                    lower_bound = mid;
                    high = mid - 1;
                } else if (st.query(i, mid) > k) {
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            if (lower_bound == -1) {
                continue;
            }

            low = lower_bound;
            high = n - 1;


            while (low <= high) {
                int mid = (low + high) / 2;
                if (st.query(i, mid) == k) {
                    upper_bound = mid;
                    low = mid + 1;
                } else if (st.query(i, mid) > k) {
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            if (upper_bound != -1) {
                ans += (upper_bound - lower_bound + 1);
            }
        }

        return ans;
    }
};

