      for(ll i=31;i>=0;--i){
        for(ll j=0;j<n;++j){
          ll b=(v[j]>>i)&1;
          mark[i][j]=b;
        }
      }
      vvi prv(32,vi(n,-1));
      for(ll i=31;i>=0;--i){
        ll zro=-1;
        for(ll j=0;j<n;++j){
          prv[i][j]=zro;
          if(mark[i][j]==0){
            zro=j;
          }
        }
      }
      ll cnt=0;
      for(ll i=0;i<n;++i){
        ll rmn=i,lmx=0,curr=1;
        for(ll j=0;j<32;++j){
          ll zro=prv[j][i];
          ll have=mark[j][i];
          ll b=(k>>j)&1;
          if(!b){
            if(have){
              if(lmx>zro) {
                curr=0;break;
              }
              rmn=min(rmn,zro);
            }
          }
          else{
            if(have){
              if(rmn<zro) {
                curr=0;break;
              }
              lmx=max(lmx,zro+1);
            }
            else{
              curr=0;
              break;
            }
          }
        }
        if(!curr)   continue;
        cnt+=(rmn-lmx+1);
      }
      return cnt;
    }
