class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        left = 0
        inner = 0
        cur_and = 2147483647
        zero_count = [0] * 31
        count = 0

        zero_bits = set()
        for i in range(31):
            if (1 << i) & k == 0:
                zero_bits.add(i)

        for right in range(len(nums)):
            if nums[right] & k != k:
                left = right + 1
                inner = right + 1
                cur_and = 2147483647
                zero_count = [0] * 31
                continue

            cur_and &= nums[right]
            for i in range(31):
                if (1 << i) & nums[right] == 0:
                    zero_count[i] += 1

            if cur_and == k:
                can_shrink = True
                for i in zero_bits:
                    if zero_count[i] == 0:
                        can_shrink = False

                while inner <= right and can_shrink:
                    for i in range(31):
                        if (1 << i) & nums[inner] == 0:
                            zero_count[i] -= 1
                            if zero_count[i] == 0:
                                can_shrink = False
                    inner += 1

                count += inner - left

        return count

