class Solution {
    const int INF = (int)1e9;
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        int64_t ans = 0;

        std::array<int, 30> a;
        for(int i = 0; i < 30; i++) {
            a[i] = INF;
        }

        for(int l = 0, r = 0; r < n; r++) {
            bool ok = true;
            for(int i = 0; i < 30; i++) {
                if((k & (1 << i)) && !(nums[r] & (1 << i))) {
                    ok = false;
                    break;
                }
            }

            if(!ok) {
                l = r + 1;
                for(int i = 0; i < 30; i++) {
                    a[i] = INF;
                }
            } else {
                int j = INF;



                for(int i = 0; i < 30; i++) {
                    if(!(nums[r] & (1 << i))) {
                        a[i] = r;
                    }
                }

                bool good = true;
                for(int i = 0; i < 30; i++) {
                    if((nums[r] & (1 << i)) && !(k & (1 << i))) {
                        if(a[i] == INF) {
                            j = INF;
                            good = false;
                            break;
                        }
                        j = std::min(j, a[i]);
                        good = false;
                    }
                }
                //std::cout << l << ' ' << r << ' ' << j << '\n';
                if(good) {
                    ans += r - l + 1;
                } else {
                    if(j != INF) {
                        ans += r - l + 1 - (r - j);
                    }
                }
            }
        }

        return ans;
    }
};

class Solution {
public:


    int lb(vector<vector<int>> &b ,int n, int idx , int k){
            int s = idx ;
            int e = n ;

            int ans=INT_MAX;

            while(s<=e){
                int mid = s+(e-s)/2;
                int val =f(b,mid,idx);
                if(val==k){
                    ans = min(ans , mid);
                    e=mid-1;
                }
                else if(val <k){
                    e=mid-1;
                }
                else {
                    s = mid+1;
                }
            }

            return ans;

    }


    int f(vector<vector<int>> &bi , int mid , int idx){
        int ans = 0;
        for (int i = 0; i < 32; i++) {
            int b = (bi[mid + 1][i] - bi[idx][i]);
            if (b==(mid-idx+1))ans += (1 << i);            
        }
        return ans;	
      }

    int ub(vector<vector<int>> &b ,int n, int idx , int k){
            int s = idx ;
            int e = n ;   
            int ans=INT_MIN;
            while(s<=e){

                int mid = s+(e-s)/2;
                int val =f(b,mid,idx);
                if(val==k){
                    ans = max(ans , mid);
                    s=mid+1;
                }
                else if(val <k){
                    e=mid-1;
                }
                else {
                    s=mid+1;
                }
            }
            return ans;

    }

    long long countSubarrays(vector<int>& nums, int k) {
        long long ans =0;
        int n = nums.size();
        vector<vector<int>> b;
        b.resize(n + 1, vector<int>(32, 0));
        for (int i = 0; i < n; i++)
            for (int j = 0; j < 32; j++)
                b[i + 1][j] = b[i][j] + ((nums[i] >> j) & 1);


        for(int i=0;i<n;i++){
           int a =ub(b,n-1,i,k);
           int c= lb(b,n-1,i,k);
           if(c==INT_MAX)continue;
           ans += (a-c+1) ;
        }

        return ans;





    }
};

class Solution {
