class Solution {
public:
  struct Node {
    int l, r, sm;
    Node *lft, *rht;
    Node(int tl, int tr, vector<int> &v): l(tl), r(tr), sm(0) {
      if (l + 1 != r) {
        lft = new Node(l, (l + r) / 2, v);
        rht = new Node((l + r) / 2, r, v);
        sm = lft->sm & rht->sm;
      } else {
        lft = rht = NULL;
        sm = v[l];
      }
    }
  };

  int query(Node *x, int l, int r) {
    if (r <= x->l || x->r <= l) {
      return INT_MAX;
    }
    if (l <= x->l && x->r <= r) {
      return x->sm;
    }
    return query(x->lft, l, r) & query(x->rht, l, r);
  }

  long long countSubarrays(vector<int>& nums, int k) {
    vector<vector<int>> actual;
    bool prv = false;
    for (int i = 0; i < nums.size(); i++) {
      bool good = true;
      for (int j = 0; j < 30; j++) {
        if ((((1 << j) & k) && ((1 << j) & nums[i])) || !((1 << j) & k)) {
        } else {
          good = false;
        }
      }
      if (good) {
        if (!prv) {
          actual.push_back(vector<int>(0));
        }
        prv = true;
        actual.back().push_back(nums[i] - k);
      } else {
        prv = false;
      }
    }
    long long ans = 0;
    for (auto v : actual) {
      Node *root = new Node(0, v.size(), v);
      int l = 0;
      for (int r = 0; r < v.size(); r++) {
        while (l <= r && query(root, l, r + 1) == 0) {
          ans += v.size() - r;
          l++;
        }
      }
    }
    return ans;
  }
};

