LL fac[N], inv[N];

void getInv() {
    fac[0] = 1;
    for (int i = 1; i < N; i++) {
        fac[i] = fac[i - 1] * i % MOD;
    }
    inv[N - 1] = qmi(fac[N - 1], MOD - 2, MOD);
    for (int i = N - 1; i; i--) {
        inv[i - 1] = inv[i] * i % MOD;
    }
}

LL comb(LL n, int k) {
    if (n < k) {
        return 0;
    }
    n %= MOD;
    LL p = 1;
    for (int i = 1; i <= k; i++) {
        p = p * (n - i + 1) % MOD;
    }
    return p * inv[k] % MOD;
}

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        map<int, LL> res; // 统计子数组数量
        vector<array<int, 3>> a; // 左端点闭区间 [a[0], a[1]] 值为 a[2]
        for (int i = 0; i < nums.size(); i++) {
            int cur = nums[i];
            for (auto &v: a) {
                v[2] &= cur; // 给定运算
            }
            a.push_back({i, i, cur});
            int p = 0; // 原地去重
            for (int i = 1; i < a.size(); i++) {
                if (a[p][2] != a[i][2]) {
                    p ++;
                    a[p] = a[i];
                } else {
                    a[p][1] = a[i][1];
                }
            }
            a.resize(p + 1);
            // 累加子数组
            for (auto &t: a) {
                res[t[2]] += t[1] - t[0] + 1;
            }
        }
        return res[k];
    }
};

class Solution {
public:
    int find(int left, int right, vector<vector<int>>& prefix){
        long long ans=0;
        for(int i=0;i<31;i++){
            if(prefix[right][i] - prefix[left][i] == right-left) ans += (1<<i );
        }
        return ans;
    }
    long long solve(vector<int>& nums, int k, vector<vector<int>>& prefix){
        long long ans=0;
        int j=0,i=0;
        while(j<nums.size()){
            int val = find(i, j+1, prefix);
            if(val <= k) {
                ans += nums.size()-j;
                i++;
            }
            else j++;
        }
        return ans;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>>prefix(n+1,vector<int>(32,0));
        for(int i=0;i<n;i++){
            for(int j=0;j<31;j++){
                int val = 0;
                if((1 << j) & nums[i]) val=1;
                prefix[i+1][j] = prefix[i][j] + (val);
            }
        }
        long long ans = solve(nums, k, prefix) ;
        if(k) ans -= solve(nums, k-1, prefix);
        return ans;

    }
};

