        int n = nums.size();
        vector<int>bits(31 , 0);
        int aux = 0;
        long long ans = 0;
        int cnt = 0;

        for(int i = 0 , j = 0 ; i < n ; i++){
            aux = get_val(bits , nums[i] , 1 , (i - j + 1));

            while(aux < k && j <= i){
                aux = get_val(bits , nums[j] , -1 , (i - j));
                j++;
            }

            ans += (i - j + 1);
        }

        return ans;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        return solve(nums , k) - solve(nums , k + 1);       
    }
