class Solution {
public:
    long long countSubarrays(vector<int>& ar, int k) {
        int n = ar.size();

        long long bit[30][n];

        memset(bit, 0, sizeof bit);

        for(int i=0; i<30; i++){
            for(int j=0; j<n; j++){
                if(ar[j]&(1<<i))bit[i][j] = 1;
            }
        }

        long long one[30][n], zero[30][n];
        memset(one, 0, sizeof one);
        memset(zero, 0, sizeof zero);

        for(int i=0; i<30; i++){
            int o = n, z = n;
            for(int j=n-1; j>=0; j--){
                if(bit[i][j])o = j;
                else z = j;
                one[i][j] = o;
                zero[i][j] = z;
            }
        }

        long long res = 0;

        for(int i=0; i<n; i++){
            long long L = i, R = n-1;
            bool f = 1;
            for(int j=0; j<30; j++){
                if(k&(1<<j)){
                    if(bit[j][i]==0){
                        f = 0;
                        break;
                    }
                    R = min(R, zero[j][i]-1);
                }
                else if(bit[j][i]){
                    L = max(L, zero[j][i]);
                }
            }
            if(!f)continue;
            if(L<=R){
                res += R-L+1;
            }
        }

        return res;


    }
};

