#define ll long long
class Solution {
public:
    ll countSubarrays(vector<int>& nums, int k) {


        /**
          good # = has at least the bits of k
          bad # = does not have at least the bits of k
          we encounter bad # -> pivot of subarray
          need to restrict to k, so somehow keep track of bits going to k


          considering dp...
          dp[i] = # subarrays at ith pos
          if bad then dp[i] = dp[i-1]
          otherwise we have the current length of the subdomain left
          still no way of tracking the intermediates

           b/c AND is destructive, i think we must track the ands
           for every element, we can add it with prev element chains
           if one of the chains ANDed with the element is the value, we succeed
           multiple chains = need to keep track of #
        */
        int n = nums.size();
        ll ret = 0;
        unordered_map<int, ll> mp;

        for(int i = 0; i < n; i++) {
            // we consider adding nums[i] to each chain value
            // will keep a sep map for caching
            int ele = nums[i];
            unordered_map<int, ll> new_m;

            // special case: just the ele
            if(ele == k) ret++;
            new_m[ele] = 1;


            for(auto& it : mp) {
                if((it.first & ele) == k) ret += it.second;
                new_m[it.first & ele] += it.second;
            }



            // swp
            mp = new_m;



        }

        // time complex may be too high






        return ret;
    }
};

