class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        long long ans = 0;

        for (int i = 0; i < n; ++i) {
            if ((a[i] & k) != k)
                continue;

            int start = i;
            while (i + 1 < n && (a[i + 1] & k) == k)
                i++;

            int l = start, r = start;
            vector<int> bits(32);
            for (; r <= i; r++) {
                for (int bit = 0; bit < 30; ++bit) {
                    if (((1 << bit) & k) || ((1 << bit) & a[r]) == 0)
                        continue;
                    bits[bit]++;                    
                }

                while (l <= r) {
                    bool ok = true;
                    for (auto x : bits)
                        if (x == r - l + 1)
                            ok = false;

                    if (ok) {
                        ans += i - r + 1;
                        for (int bit = 0; bit < 30; ++bit) {
                            if (((1 << bit) & k) || ((1 << bit) & a[l]) == 0)
                                continue;
                            bits[bit]--;
                        }
                        l++;
                    } else {
                        break;
                    }                    
                }
            }
        }


        return ans;
    }
};

