class Solution {
    HashMap<Integer, HashMap<Integer, Long>> dp;
    public long countSubarrays(int[] nums, int k) {
        dp = new HashMap<>();
        return f(0, -1, nums, k);
    }
    long f(int i, int and, int nums[], int k){
        if(i == nums.length){
            return 0;
        }
        if(dp.get(i) != null && dp.get(i).get(and) != null) return dp.get(i).get(and);
        long cnt = 0;
        if(and == -1){
            cnt += (nums[i] == k ? 1 : 0)+f(i+1, nums[i], nums, k);
            cnt += f(i+1, and, nums, k);
        }
        else{
            cnt = (cnt+(k == (nums[i]&and) ? 1 : 0)+f(i+1, nums[i]&and, nums, k));
        }
        if(dp.get(i) == null) dp.put(i, new HashMap<>());
        dp.get(i).put(and, cnt);
        return cnt;
    }
}

