class BitCounter:
    max_bits = 30

    def __init__(self):
        self.num_count = 0
        self.bit_count = [0] * self.max_bits

    def add(self, value):
        self.num_count += 1
        for i in range(self.max_bits):
            self.bit_count[i] += bool(value & 1 << i)

    def remove(self, value):
        self.num_count -= 1
        for i in range(self.max_bits):
            self.bit_count[i] -= bool(value & 1 << i)

    def get_and_value(self):
        value = 0
        for i in range(self.max_bits):
            if self.bit_count[i] == self.num_count:
                value |= 1 << i
        return value

