class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        unordered_map<int, int> count; // To store the count of previous results
        int currentAnd = 0;
        long long result = 0;

        for (int num : nums) {
            unordered_map<int, int> newCount; // To store current results

            // Check if the current element itself equals k
            if (num == k) {
                ++result; // Single element subarray
            }

            // Iterate through previous results
            for (auto& p : count) {
                int newAnd = p.first & num;

                // If the new AND result equals k, update the result count
                if (newAnd == k) {
                    result += p.second;
                }

                // Update current results map
                newCount[newAnd] += p.second;
            }

            // Update current results map for the current element
            ++newCount[num];

            // Replace count with newCount for the next iteration
            count = move(newCount);
        }

        return result;
    }
};

class Solution {
    public long countSubarrays(int[] nums, int k) {
