class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans = 0;
        int sz = nums.size();
        int pref[sz][31];
        int suff[sz][31];
        for (int i = 0; i < sz; i++) {
            for (int j = 0; j < 31; j++) {
                pref[i][j] = 0;
                suff[i][j] = sz;
            }
        }
        for (int i = 0; i < sz; i++) {
            for (int j = 0; j < 31; j++) {
                if (i) pref[i][j] = pref[i-1][j];
                if (((1LL<<j)&nums[i])) pref[i][j]++;
            }
        }
        for (int i = sz-1; i >= 0; i--) {
            for (int j = 0; j < 31; j++) {
                if (i < sz-1) suff[i][j] = suff[i+1][j];
                if (((1LL<<j)&nums[i]) == 0) suff[i][j] = i;
            }
        }
        for (int i = 0; i < sz; i++) {
            int mx = 0;
            for (int j = 0; j < 31; j++) {
                if (((1LL<<j)&k) == 0) {
                    mx = max (mx, suff[i][j]);
                }
            }
            if (mx != sz) {
                int f = 0;
                int sum = 0;
                for (int j = 0; j < 31; j++) {
                    sum = pref[mx][j];
                    if (i) sum -= pref[i-1][j];
                    if (sum == (mx-i+1)) f += (1LL<<j);
                }
                if (f == k) {
                    ///cout << mx << endl;
                    int l = mx, r = sz-1, mid, pos = mx;
                    while (l <= r) {
                        mid = (l+r)/2;
                        int g = 0;
                        int val;
                        for (int j = 0; j < 31; j++) {
                            val = pref[mid][j];
                            if (i) val -= pref[i-1][j];
                            if (val && val == (mid-i+1)) g += (1LL<<j);
                        }
                        ///cout << g << endl;
                        if (g == k) {
                            pos = mid;
                            l = mid+1;
                        }
                        else r = mid-1;
                    }
                    ///cout << pos << endl;
                    ans += (pos-mx+1);
                }
            }
        }
        return ans;
    }
};

