class Solution {
public:
    vector<int> segmentTree;

    void build(vector<int>& arr, int start, int end, int index) {
        if (start == end) {
            segmentTree[index] = arr[start];
            return;
        }
        int mid = (start + end) / 2;
        int left = 2 * index;
        int right = 2 * index + 1;
        build(arr, start, mid, left);
        build(arr, mid + 1, end, right);
        segmentTree[index] = segmentTree[left] & segmentTree[right];
    }

    void update(vector<int>& arr, int start, int end, int index, int pos, int value) {
        if (start == end) {
            arr[pos] = value;
            segmentTree[index] = arr[pos];
            return;
        }
        int mid = (start + end) / 2;
        if (pos <= mid) {
            update(arr, start, mid, 2 * index, pos, value);
        } else {
            update(arr, mid + 1, end, 2 * index + 1, pos, value);
        }
        segmentTree[index] = segmentTree[2 * index] & segmentTree[2 * index + 1];
    }

    int query(int start, int end, int index, int l, int r) {
        if (l <= start && end <= r) {
            return segmentTree[index];
        }
        if (l > end || r < start) {
            return INT_MAX;  
        }
        int mid = (start + end) / 2;
        int leftValue = query(start, mid, 2 * index, l, r);
        int rightValue = query(mid + 1, end, 2 * index + 1, l, r);
        return leftValue & rightValue;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        if (n == 0) return 0;

        segmentTree.resize(4 * n, INT_MAX);  
        build(nums, 0, n - 1, 1);

        long long count = 0;
        unordered_map<long long, long long> prev_calc;

        for (int i = 0; i < n; ++i) {
            unordered_map<long long, long long> curr_calc;

            if (nums[i] == k) {
                ++count;
            }
            curr_calc[nums[i]] = 1;

            for (auto& [value, frequency] : prev_calc) {
                long long newAndResult = value & nums[i];
                if (newAndResult == k) {
                    count += frequency;
                }
                curr_calc[newAndResult] += frequency;
            }

            prev_calc = curr_calc;
        }

        return count;
    }
};

class Solution {
public:
    long long int calc(vector<int>&v, int k){
        int n = v.size();
        long long int ans = 0;

        vector<vector<int>> dp(n+1, vector<int> (32,0));
        for(int j=1; j<=n; j++){
            for(int i=0; i<32; i++){
                dp[j][i] += dp[j-1][i];
            }
            for(int i=0; i<32; i++){
                if(v[j-1] & (1LL<<i)) dp[j][i]++;
            }
        }

        // for(auto x: dp){
        //     for(auto y:x) cout<<y<<" "; cout<<'\n';
        // }

        int j = 1;
        for(int i=1; i<=n; i++){
            while(j<=n && j<=i){
                int temp=0;
                for(int a=0; a<32; a++){
                    if(dp[i][a]-dp[j-1][a]==i-j+1) temp|=(1LL<<a);
                }
                if(temp==k){
                    ans += n-i+1;
                    j++;
                }
                else break;
            }
        }
        return ans;
    }
    long long countSubarrays(vector<int>& nums, int k) {
        vector<int> temp;
        int n = nums.size();
        long long ans = 0;
        for(int i=0; i<n; ){
            while(i<n && ((nums[i]&k) == k)){
                temp.push_back(nums[i]);
                i++;
            }
            if(temp.size()){ 
                ans += calc(temp, k);
                temp.clear();
            }
            else i++;
        }
        return ans;
    }
};

