        vector<vector<int>> pre(n + 1, vector<int>(35, 0));
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < 32; ++j)
            {
                if (i > 0)
                    pre[i][j] = pre[i - 1][j];
                if (nums[i] & (1 << j))
                    pre[i][j]++;
            }
        auto getand = [&](int l, int r)
        {
            int res = 0;
            for (int i = 0; i < 32; ++i)
            {
                int cur = pre[r][i];
                if (l > 0)
                    cur -= pre[l - 1][i];
                if (cur == r - l + 1)
                    res |= (1 << i);
            }
            return res;
        };
        long long ans = 0;
        for (int i = 0; i < n; ++i)
        {
            int st = -1, en = -1;
            int lo = i + 1;
            int hi = n - 1;
            int op = 0;
            while (lo <= hi)
            {
                int mid = lo + (hi - lo) / 2;
                int cur = getand(i, mid);
                if (cur > k)
                {
                    lo = mid + 1;
                }
                else if (cur < k)
                    hi = mid - 1;
                else if (cur == k)
                {
                    st = mid;
                    hi = mid - 1;
                }
            }

            lo = i;
            hi = n - 1;
            op = 0;
            while (lo <= hi)
            {
                int mid = lo + (hi - lo) / 2;
                if (getand(i, mid) < k)
                    hi = mid - 1;

                else
                {
                    en = mid;
                    lo = mid + 1;
                }
            }
            if (st != -1 && en != -1)
                ans += en - st + 1;
            if (nums[i] == k)
                ans++;
        }

        return ans;
    }
};

