class SegTree{
    public:
    vector<long long>a;
    vector<long long>seg;
    SegTree(int n)
    {
        a.resize(n,0);
        seg.resize(4*n,0);
    }

    void build(int idx, int low, int high)
    {
        if(low==high)
        {
            seg[idx] = a[low];
            return;
        }
        int mid = low+(high-low)/2;
        build(2*idx+1,low,mid);
        build(2*idx+2,mid+1,high);

        //to be changed accordingly
        seg[idx] = seg[2*idx+1]&seg[2*idx+2];
        return;
    }

    long long query(int idx, int low, int high, int l, int r)
    {
        if(low>=l && high<=r)
        {
            return seg[idx];
        }

        //to be changed accordingly
        if(high<l || low>r)
        {
            return -1;
        }

        int mid = low+(high-low)/2;
        //to be changed accorgingly
        long long left = query(2*idx+1,low,mid,l,r);
        long long right = query(2*idx+2,mid+1,high,l,r);
        if(left==-1 && right==-1)
        {
            return -1;
        }else if(left==-1) return right;
        else if(right==-1) return left;
        else return left&right;

    }


};
class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        SegTree st(n);
        for(int i=0; i<n; i++)
        {
            st.a[i] = a[i];
        }
        st.build(0,0,n-1);
        long long ans = 0;
        for(int i=0; i<n; i++)
        {
            int low = lower(st,i,k,n);
            int high = upper(st,i,k,n);
            if(low!=-1)
            {
                ans+=(long long)(high-low+1);
            }
            //if(i==1) return low;
        }

        //return st.query(0,0,n-1,1,3);
        return ans;
    }
    int lower(SegTree&st,int i,int k,int n)
    {
        int l=i;
        int h = n-1;
        int ans = -1;
        while(l<=h)
        {
            int m = l+(h-l)/2;
            int res = st.query(0,0,n-1,i,m);

            if(res<k)
            {
                h = m-1;
            }else if(res==k)
            {
                ans = m;
                h = m-1;
            }else{
                l = m+1;
            }
        }
        return ans;
    }
    int upper(SegTree&st,int i,int k,int n)
    {
        int l=i;
        int h = n-1;
        int ans = -1;
        while(l<=h)
        {
            int m = l+(h-l)/2;
            int res = st.query(0,0,n-1,i,m);
            if(res<k)
            {
                h = m-1;
            }else if(res==k)
            {
                ans = m;
                l = m+1;
            }else{
                l = m+1;
            }
        }
        return ans;
    }
};

