    ll power(ll x,ll y,int p=1000000007)
      {
        ll res = 1;

        x = x % p; 

        while (y > 0) 
        {
            if (y & 1)
                res = (res * x) % p;

            y = y >> 1; 
            x = (x * x) % p;
        }
        return res;
    }


    ll modInverse(ll n,int p=1000000007)
    {
        return power(n, p - 2, p);
    }

    ll nCr(ll n,ll r, int p=1000000007)
    {

        if (n < r)
            return 0;
        if (r == 0)
            return 1;

        ll fac[n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++)
            fac[i] = (fac[i - 1] * i) % p;

        return (fac[n] * modInverse(fac[r], p) % p
                * modInverse(fac[n - r], p) % p)
               % p;
    }
