class Solution {
    fun countSubarrays(nums: IntArray, k: Int): Long {
        val n = nums.size
        var count: Long = 0
        var prev = mutableMapOf<Long, Long>()

        for (i in 0 until n) {
            val curr = mutableMapOf<Long, Long>()

            if (nums[i] == k) {
                count++
            }
            curr[nums[i].toLong()] = 1

            for (entry in prev) {
                val (value, freq) = entry
                val newAndResult = value and nums[i].toLong()
                if (newAndResult == k.toLong()) {
                    count += freq
                }
                curr[newAndResult] = curr.getOrDefault(newAndResult, 0) + freq
            }

            prev = curr
        }

        return count
    }
}

