class SegmentTree{
private:

	vector<ll> tree;
	ll N;

	void buildTree(ll l,ll r,int i,vector<ll>& arr){
		if (l==r){
			tree[i]=arr[l];
			return;
		}
		ll mid = (l+r)/2;
		buildTree(l,mid,2*i+1,arr);
		buildTree(mid+1,r,2*i+2,arr);
		tree[i] = (tree[2*i+1]&tree[2*i+2]);
	}

    ll query(ll x,ll y,ll l,ll r,ll i){
		if(r<x || l>y)return ((1LL<<34)-1);//no overlap (all ones) 
		if(l>=x && r<=y)return tree[i];//complete overlap

		ll mid = (l+r)/2;
		return (query(x,y,l,mid,2*i+1)&query(x,y,mid+1,r,2*i+2));
	}

