class SparseTable {
   public:
    int N;
    vector<vector<int>> t;
    SparseTable(int n, vector<int>& a) {
        this->N = n;
        t.resize(N + 1);
        for (auto& v : t) {
            v.resize(31);
        }
        for (int i = 1; i <= n; ++i) t[i][0] = a[i - 1];
        for (int k = 1; k < 31; ++k) {
            for (int i = 1; i + (1 << k) - 1 <= n; ++i) {
                t[i][k] = combine(t[i][k - 1], t[i + (1 << (k - 1))][k - 1]);
            }
        }
    }
    int query(int l, int r) {
        int k = 31 - __builtin_clz(r - l + 1);
        return combine(t[l][k], t[r - (1 << k) + 1][k]);
    }

   private:
    int combine(int a, int b) { return a & b; }
};

class Solution {
   public:
    long long countSubarrays(vector<int>& a, int k) {
        long long ans = 0;
        int n = a.size();
        SparseTable st(n, a);
        for (int i = 0; i < n; i++) {
            int l = i, r = n - 1;
            int last_pos = -1;
            while (l <= r) {
                int mid = l + (r - l) / 2;
                int sub_and = st.query(i + 1, mid + 1);
                if (sub_and > k) {
                    l = mid + 1;
                } else if (sub_and == k) {
                    last_pos = mid;
                    l = mid + 1;
                } else {
                    r = mid - 1;
                }
            }
            int first_pos = -1;
            l = i, r = n - 1;
            while (l <= r) {
                int mid = l + (r - l) / 2;
                int sub_and = st.query(i + 1, mid + 1);
                if (sub_and > k) {
                    l = mid + 1;
                } else if (sub_and == k) {
                    first_pos = mid;
                    r = mid - 1;
                } else {
                    r = mid - 1;
                }
            }
            if (last_pos != -1 and first_pos != -1) {
                ans += (last_pos - first_pos + 1);
            }
        }
        return ans;
    }
};

