        memset(pre,0,sizeof(pre));
        for(int i=0;i<30;i++){
            for(int j=1;j<=n;j++){
                pre[i][j]=pre[i][j-1]+((nums[j-1] & (1<<i)) > 0);
            }
        }
        long long ans=0;
        for(int j=0;j<n;j++){
            int l=j+1,r=n;
