class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        constexpr int K = 17;

        int n = nums.size();

        vector<vector<int>> st(K + 1, vector<int>(n + 1));

        copy(nums.begin(), nums.end(), st[0].begin());

        for (int i = 1; i <= K; i++) {
            for (int j = 0; j + (1 << i) <= n; j++) {
                st[i][j] = st[i - 1][j] & st[i - 1][j + (1 << (i - 1))];
            }
        }

        const auto orq = [&](int L, int R) {
            int i = log2_floor(R - L + 1);
            return st[i][L] & st[i][R - (1 << i) + 1];
        };

        long long res = 0;

        const auto left_match = [&](int i) {
            int left = i;
            int right = n - 1;
            int best = -1;
            while (right - left >= 0) {
                int mid = (left + right) >> 1;

                int q = orq(i, mid);

                if (q < k) {
                    right = mid - 1;
                } else if (q > k) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                    best = mid;
                }
            }

            return best;
        };

        const auto right_match = [&](int i) {
            int left = i;
            int right = n - 1;
            int best = -1;
            while (right - left >= 0) {
                int mid = (left + right) >> 1;

                int q = orq(i, mid);

                if (q < k) {
                    right = mid - 1;
                } else if (q > k) {
                    left = mid + 1;
                } else {
                    left = mid + 1;
                    best = mid;
                }
            }

            return best;
        };

        for (int i = 0; i < n; ++i) {
            int left = left_match(i);

            if (left == -1) {
                continue;
            }

            int right = right_match(i);

            // cout << i << ' ' << left << ' ' << right << endl;

            res += right - left + 1;
        }

        return res;
    }

    int log2_floor(unsigned long i) {
        return std::bit_width(i) - 1;
    }
};

