            long long lower_bnd = -1, upper_bnd = -1,left=i,right=n-1;

            while (left <= right)
            {
                long long mid = (left + right) >> 1;
                if(segtree.query(i,mid) > k)
                {
                    left = mid + 1;
                }
                else if(segtree.query(i,mid) == k)
                {
                    lower_bnd = mid;
                    right = mid - 1;
                }
                else
                {
                    right = mid - 1;
                }
            }
            left = i, right = n - 1;
            while (left <= right)
            {
                long long mid = (left + right) >> 1;
                if(segtree.query(i,mid) > k)
                {
                    left = mid + 1;
                }
                else if(segtree.query(i,mid) == k)
                {
                    upper_bnd = mid;
                    left = mid + 1;
                }
                else
                {
                    right = mid - 1;
                }
            }
            if(lower_bnd != -1)
                solution += (upper_bnd - lower_bnd + 1);
        }
        return solution;
    }
};

