template <typename T>
struct SparseTable {
    vector<vector<T>> table;
    function<T(T&, T&)> Compare;

    SparseTable(){}
    SparseTable(const vector<T>& nums, function<T(T&, T&)> comp) { build(nums, comp); }

    void build(const vector<T>& nums, function<T(T&, T&)> comp) {
        Compare = comp;
        int n = nums.size();
        int logN = log2(n) + 1;

        table.resize(n, vector<T>(logN));

        // Fill the base cases
        for(int i = 0; i < n; ++i)
            table[i][0] = nums[i];

        // Fill the rest of the table
        for(int j = 1; (1 << j) <= n; ++j)
            for(int i = 0; i + (1 << j) - 1 < n; ++i)
                table[i][j] = Compare(table[i][j - 1], table[i + (1 << (j - 1))][j - 1]);
    }

    T find(int left, int right) {
        int k = log2(right - left + 1);
        return Compare(table[left][k], table[right - (1 << k) + 1][k]);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        const int n = nums.size();
        SparseTable<int> table(nums, [](auto& A, auto& B){
            return A & B;
        });

        auto calc = [&](int begin) -> int {
            if(table.find(begin, begin) < k) return -1;

            int left = begin;
            int right = n - 1;
            int whr = n - 1;
            while(left <= right){
                int mid = left + (right - left) / 2;
                if(table.find(begin, mid) <= k)
                    whr = mid, right = mid - 1;
                else
                    left = mid + 1; 
            }

            return whr;
        };

        // for(int i = 0; i < n; i++){
        //     int got = nums[i];
        //     for(int j = i; j < n; j++){
        //         got &= nums[j];
        //         if(got != k) continue;
        //         debug(i) debug(j) e_
        //     }
        // }

        int64_t ans = 0;
        for(int i = 0; i < n; i++){
            int begin = calc(i);
            if(begin == -1) continue;
            if(table.find(i, begin) != k) continue;

            int left = begin;
            int right = n - 1;
            int end = begin;
            while(left <= right){
                int mid = left + (right - left) / 2;
                if(table.find(i, mid) >= k)
                    end = mid, left = mid + 1;
                else
                    right = mid - 1;
            }

            // debug(i)
            // debug(begin)
            // debug(end)
            // debug(table.find(i, end)) e_
            ans += end - begin + 1;
        }

        return ans;
    }
};

