class SGTree{
   vector<int> sg;
   public:
    SGTree(int n){
     sg.resize(4*n+1);
   }

   void build(int ind ,int low ,int high,vector<int>& arr){
      if(low==high){
          sg[ind] = arr[low];
          return ;
      }

      int mid = (low+high) >> 1;
      build(2*ind+1,low,mid,arr);
      build(2*ind+2,mid+1,high,arr);
      sg[ind] = sg[2*ind+1]&sg[2*ind+2];
   }
   //get minimum element in a range
   int query(int ind ,int low,int high,int l,int r){
      //non overlap 
      // l r low high  or low high l r
      if(r < low or l > high) return INT_MAX;
      // complete overlap
      // l low high r
      if(low >= l and high <=r) return sg[ind];

      int mid = (high+low) >> 1;
      int left = query(2*ind+1,low,mid,l,r);
      int right = query(2*ind+2,mid+1,high,l,r);
      return left&right;
   }
};

class Solution {
public:
    long long countSubarrays(vector<int>& arr, int k) {
        int n = arr.size();
        SGTree t1 = SGTree(n);
         t1.build(0 ,0 ,n-1,arr);
         long long ans = 0;
        for(int i=0;i<n;i++){
            int low = i;
            int high = n-1;
            int ind1 = -1;
            while(low<=high){
                int mid = (low+high)>>1;
                int a = t1.query(0,0,n-1,i,mid);
                if(a<=k-1){
                    high=mid-1;
                    ind1 = mid;
                }
                else{
                    low = mid+1;
                }
            }
            ind1=low;
             low = i;
             high = n-1;
            int ind2 = -1;
            while(low<=high){
                int mid = (low+high)>>1;
                int a = t1.query(0,0,n-1,i,mid);
                if(a<=k){
                    high=mid-1;
                    ind2 = mid;
                }
                else{
                    low = mid+1;
                }
            }
            ind2 = low;
            ans+=((long long)ind1-(long long)ind2);
        }
        return ans;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>>bit(n+1,vector<int>(33,0));
        for(int i=0;i<n;i++){
            int x = nums[i];
            int ind = 0;
            while(x){
                if(x&1){
                    bit[i+1][ind] = bit[i][ind] + 1; 
                }
                ind++;
                x>>=1;
            }
        }
        int l = 0;
        int r = 0;
        long long ans = 0;
        for(int i=0;i<n;i++){
            int l = i;
            int r = n-1;
            int l_i = -1;
            bool f = 0;
            while(l<=r){
                int mid = (l+r)/2;
                int p = 0;
                for(int j =0;j<33;j++){
                    int diff = bit[mid+1][j] - bit[i][j];
                    if(diff==mid-i+1){
                        p|=(1<<j);
                    }
                }
                if(p==k)f=1;

                if(p>k){
                    l = mid+1;
                }
                else{
                    l_i = mid;
                    r = mid-1;
                }
            }
            if(l_i==-1 or f==0)continue;
            l = i;
            r = n-1;
            int r_i = -1;
            while(l<=r){
                int mid = (l+r)/2;
                int p = 0;
                for(int j =0;j<33;j++){
                    int diff = bit[mid+1][j] - bit[i][j];
                    if(diff==mid-i+1){
                        p|=(1<<j);
                    }
                }
                if(p<k){
                    r = mid-1;
                }
                else{
                    r_i = mid;
                    l = mid+1;
                }
            }
            ans+=(r_i-l_i+1);
        }
        return ans;
    }
};

