class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        nbit=[0]*32
        check=[True if (k&(1<<i))==0 else False for i in range(32)]
        lo,hi=0,0
        res=0
        def can_reduce(t,l):
            # print(t,l)
            bit=0
            for _ in range(32):
                if check[bit]:
                    if (t&1)==1:
                        if nbit[bit]-1==l:
                            return False
                    else:
                        if nbit[bit]==l:
                            return False
                else:
                    if nbit[bit]==l:
                        return False
                t>>=1
                bit+=1
            return True
        def can_fit(l):
            for i,e in enumerate(nbit):
                if check[i] and e>=l:
                    return False
            return True
        # sliding windows
        for i,e in enumerate(nums):
            if (e&k)==k:
                bit=0
                t=e
                while t>0:
                    if (t&1)==1:
                        nbit[bit]+=1 
                    t>>=1
                    bit+=1
                while hi<i and can_reduce(nums[hi],i-hi):
                    bit=0
                    t=nums[hi]
                    while t>0:
                        if (t&1)==1:
                            nbit[bit]-=1 
                        t>>=1
                        bit+=1
                    hi+=1
                # read hi
                if can_fit(i-hi+1): res+=hi-lo+1
            else:
                lo,hi=i+1,i+1
                nbit=[0]*32
            # print(lo,hi,i,res,nbit[:5])
        return res

