    void buildSparseTable(int n,vector<int>&arr) {
    for (int i = 0; i < n; ++i) {
        sparseTable[i][0] = arr[i];
    }

    for (int j = 1; (1 << j) <= n; ++j) {
        for (int i = 0; (i + (1 << j) - 1) < n; ++i) {
            sparseTable[i][j] = (sparseTable[i][j-1] & sparseTable[i + (1 << (j - 1))][j - 1]);
        }
    }
}

int AND(int L, int R) {
    int j = log2(R - L + 1);
    return (sparseTable[L][j] & sparseTable[R - (1 << j) + 1][j]);
}
    int Greater(int ind, vector<int> &ar, int k)
    {
        int lo = ind, hi = n - 1, p =  ind - 1;
        while (lo <= hi)
        {
            int mid = (lo + hi) / 2;
            if (AND(ind, mid) > k)
            {
                p = mid;
                lo = mid + 1;
            }
            else
                hi = mid - 1;
        }
        return p;
    }
    int GreaterEqual(int ind, vector<int> &ar, int k)
    {
        int lo = ind, hi = n - 1, p =  - 1;
        while (lo <= hi)
        {
            int mid = (lo + hi) / 2;
            if (AND(ind, mid) >= k)
            {
                p = mid;
                lo = mid + 1;
            }
            else
                hi = mid - 1;
        }
        return p;
    }

public:
    long long countSubarrays(vector<int> &ar, int k)
    {
        n = ar.size();
        pf = vector<vector<int>>(32, vector<int>(n + 2));
        sparseTable=vector<vector<int>>(n+2, vector<int>(32));
        buildSparseTable(n,ar);
        for(int i=0;i<32;i++){
            for(int j=0;j<n;j++){
                if(ar[j]&(1LL<<i)) pf[i][j]=1;
                if(j) pf[i][j]+=pf[i][j-1];
            }
        }
        long long ans = 0;
        for (int i = 0; i < n; i++)
        {
            int G=Greater(i, ar, k),GE=GreaterEqual(i, ar, k);
            if(GE>G)
            ans += GE - G;
        }
        return ans;
    }
};

