int N;
class segmentTree
{
public:
    vector<int> segTree, lazy;
    segmentTree(vector<int> &v)
    {
        segTree.resize(4 * N - 1);
        lazy.resize(4 * N - 1);
        build(v);
    }

    void build(vector<int> &v, int start = 0, int end = N - 1, int ind = 0)
    {
        // time complexity : n + n/2 + n/4 + n+8 + ....  = O(n);
        if (start == end)
        {
            segTree[ind] = v[start];
            return;
        }

        int mid = (start + end) / 2;
        build(v, start, mid, 2 * ind + 1);
        build(v, mid + 1, end, 2 * ind + 2);

        segTree[ind] = segTree[2 * ind + 1] + segTree[2 * ind + 2];
    }

    void update(int pos, int val, int start = 0, int end = N - 1, int ind = 0)
    { // time complexity : O(logn)
        if (start == end)
        {
            segTree[ind] += val;
            return;
        }

        int mid = (start + end) / 2;
        if (pos <= mid)
        {
            update(pos, val, start, mid, 2 * ind + 1);
        }
        else
        {
            update(pos, val, mid + 1, end, 2 * ind + 2);
        }

        segTree[ind] = segTree[2 * ind + 1] + segTree[2 * ind + 2];
    }

    int query(int l, int r, int start = 0, int end = N - 1, int ind = 0)
    { // time complexity: O(logn)
        // complete overlap
        if (start >= l and end <= r)
            return segTree[ind];

        // no overlap
        if (end < l || start > r)
            return 0;

        // partial overlap
        int mid = (start + end) / 2;
        int left = query(l, r, start, mid, 2 * ind + 1);
        int right = query(l, r, mid + 1, end, 2 * ind + 2);

        return left + right;
    }

    // Range update
    void range_Update(int l, int r, int val, int ind = 0, int low = 0, int high = N - 1)
    {
        // first complete the previous updates
        if (lazy[ind] != 0)
        {
            segTree[ind] += (high - low + 1) * lazy[ind];
            if (low != high)
            {
                lazy[2 * ind + 1] += lazy[ind];
                lazy[2 * ind + 1] += lazy[ind];
            }
            lazy[ind] = 0;
        }

        // No Overlap
        if (high < l or r < low)
            return;

        // Complete Overlap
        if (low >= l and high <= r)
        {
            // update the node
            segTree[ind] += (high - low + 1) * val;

            // propagte the change down if it is not a leaf node
            if (low != high)
            {
                lazy[2 * ind + 1] += val;
                lazy[2 * ind + 2] += val;
            }
            return;
        }

        // partial Ovelap
        int mid = (low + high) >> 1;
        range_Update(l, r, val, 2 * ind + 1, low, mid);
        range_Update(l, r, val, 2 * ind + 2, mid + 1, high);
        segTree[ind] = segTree[2 * ind + 1] + segTree[2 * ind + 2];
    }

    int range_query(int l, int r, int ind = 0, int low = 0, int high = N - 1)
    {
        // first complete the previous updates
        if (lazy[ind] != 0)
        {
            segTree[ind] += (high - low + 1) * lazy[ind];
            if (low != high)
            {
                lazy[2 * ind + 1] += lazy[ind];
                lazy[2 * ind + 1] += lazy[ind];
            }
            lazy[ind] = 0;
        }

        // No Overlap
        if (high < l or r < low)
            return 0;

        // Complete Overlap
        if (low >= l and high <= r)
            return segTree[ind];

        // partial Ovelap
        int mid = (low + high) >> 1;
        int left = range_query(l, r, 2 * ind + 1, low, mid);
        int right = range_query(l, r, 2 * ind + 2, mid + 1, high);
        return left + right;
    }
};

