class Solution {
public:
    long long func(vector<int> &v,int k){

        int n = v.size();
        vector<int> hash(32, 0);
        long long ans = 0;
        int l = 0;
        int r = 0;

        while(l<n && r<n){
            int temp = v[r];
            int now = 0;
            for(int i=0;i<32;i++){
                if(temp%2){
                    hash[i]++;
                }
                temp = temp/2;
            }
            for(int i=0;i<32;i++){
                if(hash[i]==(r-l+1)){
                    now += pow(2,i);
                }
            }

            while(l<=r && now<=k){
                ans += (r-n);
                int temp2 = v[l];
                int alt = 0;
                for(int i=0;i<32;i++){
                    if(temp2%2){
                        hash[i]--;
                    }
                    temp2 = temp2/2;
                }
                for(int i=0;i<32;i++){
                    if(hash[i]!=0 && hash[i]==(r-l)){
                        alt += pow(2,i);
                    }
                }
                l++;
                now = alt;
            }
            r++;
        }

        return ans;
    }

    long long countSubarrays(vector<int>& v, int k) {

        return -func(v,k)+func(v,k-1);
    }
};

class Solution {
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int m = 31;
        var last0 = new int[m];
        Arrays.fill(last0, -1);
        long result = 0;
        for(int i = 0; i < n; ++i) {

            for(int j = 0; j < m; ++j) {
                int mask = (1 << j);
                if ((nums[i] & mask) == 0) {
                    last0[j] = i;
                }
            }

            // end is always i.

            int high = i;
            int low = -1;

            for(int j = 0; j < m; ++j) {
                int mask = (1 << j);
                if ((k & mask) == 0) {
                    // need at least one 0, so start <= min(last0[j]).
                    if (last0[j] < 0) { // all previous is 1.
                        high = -1;
                    } else {
                        high = Math.min(high, last0[j]);
                    }
                } else {
                    // need all 1, so start > max(last0[j]).
                    if (last0[j] < 0) { // all previous is 1.
                        // does not move low.
                    } else {
                        low = Math.max(low, last0[j]);
                    }
                }
            }

            // (low, high] is valid.
            result += Math.max(0, high - low);
        }
        return result;
    }
}

