class Solution {
    public long countSubarrays(int[] nums, int k) {
        return countAtLeast(nums, k) - countAtLeast(nums, k + 1);
    }
    public long countAtLeast(int[] nums, int k) {
        long ans = 0;
        int n = nums.length;
        int[][] psa = new int[n + 1][32];
        int[] zero = new int[n + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 32; j++) {
                psa[i + 1][j] = psa[i][j] + (nums[i] >> j & 1);
            }
            zero[i + 1] = zero[i] + (nums[i] == 0 ? 1 : 0);
        }
        int and = (1<<31) - 1;
        for (int i = 1, j = 1; j <= n; j++) {
            and &= nums[j - 1];
            while (and < k && i < j) {
                i++;
                if (zero[j] - zero[i - 1] != 0) {
                    i = j;
                    break;
                }
                and = 0;
                for (int l = 0; l < 32; l++) {
                    int cnt = psa[j][l] - psa[i - 1][l];
                    if (cnt == 0) continue;
                    and |= (1 << l) * ((cnt == j - i + 1) ? 1 : 0);
                }
            }
            if (and < k && i == j) {
                and = (1<<31) - 1;
                i++;
                continue;
            }
            ans += (j - i + 1);
        }
        return ans;
    }
}
