class SegmentTree {
    int tree[];
    int n;

    public SegmentTree(int n) {
        this.tree = new int[(4 * n) + 1];
        this.n = n;
    }

    public void buildTree(int arr[]) {
        buildTree(arr, 0, n - 1, 0);
    }

    private void buildTree(int arr[], int low, int high, int x) {
        if(low > high) return;
        if(low == high) {
            this.tree[x] = arr[low];
            return;
        }

        int mid = low + (high - low) / 2;

        buildTree(arr, low, mid, (2 * x) + 1);
        buildTree(arr, mid + 1, high, (2 * x) + 2);

        this.tree[x] = (this.tree[(2 * x) + 1] & this.tree[(2 * x) + 2]);
    }

    public int query(int l, int h) {
        if(l > h) return Integer.MAX_VALUE;
        return query(0, n - 1, l, h, 0);
    }

    private int query(int low, int high, int l, int h, int x) {
        if(l <= low && high <= h)
            return this.tree[x];
        if(h < low || high < l)
            return Integer.MAX_VALUE;

        int mid = low + (high - low) / 2;

        return (query(low, mid, l, h, (2 * x) + 1) & query(mid + 1, high, l, h, (2 * x) + 2));
    }
}
class Solution {

    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        SegmentTree st = new SegmentTree(nums.length);

        // st.buildTree(nums);

        int prefixAnd[][] = new int[n][30];
        int prefix[] = new int[30];

        for(int i = 0; i < n; i++) {
            for(int j = 0; j < 30; j++) {
                if((nums[i] & (1 << j)) > 0) {
                    prefix[j]++;
                }
            }

            for(int j = 0; j < 30; j++)
                prefixAnd[i][j] = prefix[j];
        }

        long ans = 0;

        for(int i = 0; i < nums.length; i++) {
            int l = lowerBound(nums, i, k, st, prefixAnd);
            if(l == -1)
                continue;

            int r = upperBound(nums, l, i, k, st, prefixAnd);

            ans += (r - l + 1);
        }

        return ans;
    }

    private int lowerBound(int nums[], int index, int k, SegmentTree st, int prefixAnd[][]) {
        int low = 0;
        int high = index;

        int ans = -1;

        while(low <= high) {
            int mid = low + (high - low) / 2;
            int val = getValue(mid, index, prefixAnd);

            if(val == k) {
                ans = mid;
                high = mid - 1;
            } else if(val > k) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        return ans;
    }

    private int upperBound(int nums[], int l, int index, int k, SegmentTree st, int prefixAnd[][]) {
        int low = l;
        int high = index;

        int ans = -1;

        while(low <= high) {
            int mid = low + (high - low) / 2;
            int val = getValue(mid, index, prefixAnd);

            if(val == k) {
                ans = mid;
                low = mid + 1;
            } else if(val > k) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        return ans;
    }

    private int getValue(int l, int r, int prefixAnd[][]) {
        int arr[] = new int[30];
        int n = r - l + 1;
        int ans = 0;

        for(int i = 0; i < 30; i++) {
            arr[i] = prefixAnd[r][i];

            if(l - 1 >= 0)
                arr[i] -= prefixAnd[l - 1][i];

            if(arr[i] == n)
                ans = ans | (1 << i);
        }

        return ans;
    }
}

