class Solution {
public:
    #define ll long long
    ll findval(ll mid,ll i,ll k, vector<vector<ll>>&pf){
        ll val=0,len=mid-i+1;
        for(ll j=0;j<=30;j++){
            if(pf[mid+1][j]-pf[i][j]>=len)val+=(1LL<<j);
        }

        return val;
    }
    ll func(ll i,ll x,vector<vector<ll>>&f){

        ll mini=1e9;
        for(ll j=0;j<=30;j++){
            if(x&(1LL<<j)){
                mini=min(mini,f[i][j]);
            }
        }
        if(mini>=1e9)mini=0;
        return mini;
    }
    long long countSubarrays(vector<int>& nums, int k) {
         int n=nums.size();

         ll ans=0,sum=0;

         vector<vector<ll>>pf(n+1,vector<ll>(31,0));
         for(int i=0;i<n;i++){
            ll x=nums[i];
            for(ll j=0;j<=30;j++){
                if(x&(1<<j))pf[i+1][j]++;
                pf[i+1][j]+=pf[i][j];
            }
         }

         vector<vector<ll>>f(n+1,vector<ll>(31,0));
         for(ll i=n-1;i>=0;i--){

             for(ll j=0;j<=30;j++){
                 ll bit=nums[i]&(1LL<<j);
                 if(bit)f[i][j]=f[i+1][j]+1;
             }
         }


         for(ll i=0;i<n;i++){
             ll lo=i,hi=n-1;

             while(hi-lo>1){
                ll mid=(lo+hi)/2;
                ll val=findval(mid,i,k,pf);

                if(val<=k)hi=mid;
                else lo=mid;
             }

            // if(findval(lo,i,k,pf)==k)ans+=f[lo];
             //else if(findval(hi,i,k,pf)==k)ans+=f[hi];

             if(findval(lo,i,k,pf)==k)ans+=func(lo,k,f);
             else if(findval(hi,i,k,pf)==k)ans+=func(hi,k,f);
             //cout<<ans<<" ";
             if(findval(lo,i,k,pf)==k)sum+=n-lo;
             else if(findval(hi,i,k,pf)==k)sum+=n-hi;
         }

         if(k==0)return sum;
         return ans;
    }
};

