class SegmentTree:
    def __init__(self, data, default=0, func=max):
        """initialize the segment tree with data"""
        self._default = default
        self._func = func
        if isinstance(data, int):
            self._len = data
            self._size = _size = 1 << (self._len - 1).bit_length()
            self.data = [default] * (2 * _size)
        else:
            self._len = len(data)
            self._size = _size = 1 << (self._len - 1).bit_length()
            self.data = [default] * (2 * _size)
            self.data[_size:_size + self._len] = data
            for i in reversed(range(_size)):
                self.data[i] = func(self.data[i + i], self.data[i + i + 1])

    def __getitem__(self, idx):
        if isinstance(idx, slice): return self.query(idx.start,idx.stop)
        return self.data[idx + self._size]

    def __setitem__(self, idx, value):
        idx += self._size
        self.data[idx] = value
        idx >>= 1
        while idx:
            self.data[idx] = self._func(self.data[2 * idx], self.data[2 * idx + 1])
            idx >>= 1

    def __len__(self):
        return self._len

    def query(self, start, stop):
        """func of data[start, stop)"""
        start += self._size
        stop += self._size

        res_left = res_right = self._default
        while start < stop:
            if start & 1:
                res_left = self._func(res_left, self.data[start])
                start += 1
            if stop & 1:
                stop -= 1
                res_right = self._func(self.data[stop], res_right)
            start >>= 1
            stop >>= 1

        return self._func(res_left, res_right)

    def __repr__(self):
        return "SegmentTree({0})".format(self.data)


class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        tr = SegmentTree(nums, (1 << 32) - 1, lambda x, y: x & y)
        n = len(nums)
        ans = 0
        s1 = 0
        s2 = 0
        for end in range(n):
            while s1 <= end and tr[s1:end + 1] < k:
                s1 += 1
            while s2 <= end and tr[s2:end + 1] <= k:
                s2 += 1
            if s1 <= end:
                ans += (s2 - s1)
        return ans

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        arr = [0]*30
        bits = bin(k)[2:][::-1]
        for i in range(len(bits)):
            arr[i] = int(bits[i])

        res = 0
        block = -1
        curr = [-1]*30
        heap = []
        for i in range(len(nums)):
            if nums[i] & k != k:
                block = i
                curr = [-1]*30
                heap = []
                continue

            bits = bin(nums[i])[2:]
            bits = (30-len(bits))*'0' + bits
            state = True
            for j in range(len(bits)):
                if bits[len(bits)-j-1] == '0' and arr[j] == 0:
                    curr[j] = i
                    heappush(heap, [i, j])
                if bits[len(bits)-j-1] == '1' and arr[j] == 0 and curr[j] == -1:
                    state = False
            if state == False:
                continue

            if heap:
                while True:
                    arr_pos, bit_pos = heappop(heap)
                    if curr[bit_pos] == arr_pos:
                        break
                heappush(heap, [arr_pos, bit_pos])
                # print('1')
                res += arr_pos-block
            else:
                # print('2')
                res += i-block
            # print(i, nums[i], res, block)
        return res

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int target) {
        int n = nums.size();
        long long count = 0;
        unordered_map<long long, long long> prevAndResults;
        for (int i = 0; i < n; ++i) {
            unordered_map<long long, long long> currentAndResults;
            if (nums[i] == target) {
                ++count;
            }
            currentAndResults[nums[i]] = 1;
            for (auto& [value, frequency] : prevAndResults) {
                long long newAndResult = value & nums[i];
                if (newAndResult == target) {
