class Solution {
private:
    long long countSubarraysEndingAtIndex(const vector<int>& nums, int k, int endIndex, unordered_map<long long, long long>& prevResults) {
        long long count = 0;
        long long num = nums[endIndex];
        if (num == k) ++count;
        for (auto& [val, freq] : prevResults) {
            long long newAndResult = val & num;
            if (newAndResult == k) count += freq;
        }
        return count;
    }
    void updatePrevResults(unordered_map<long long, long long>& prevResults, long long num) {
        unordered_map<long long, long long> currResults;
        for (auto& [val, freq] : prevResults) {
            long long newAndResult = val & num;
            currResults[newAndResult] += freq;
        }
        currResults[num]++;
        prevResults = move(currResults); 
    }
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long count = 0;
        unordered_map<long long, long long> prevResults;
        for (int i = 0; i < n; ++i) {
            count += countSubarraysEndingAtIndex(nums, k, i, prevResults);
            updatePrevResults(prevResults, nums[i]);
        }
        return count;
    }
};

