class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        auto f = [&](int x) {
            int i = 0, j = 0;
            long long ans = 0;
            vector<int> bit(32, 0);
            auto add = [&](int x) -> void {
                for (int i = 0; i < 32; i++) {
                    if ((x & (1 << i)) == 0) {
                        bit[i]++;
                    }
                }
            };
            auto subtract = [&](int x) -> void {
                for (int i = 0; i < 32; i++) {
                    if ((x & (1 << i)) == 0) {
                        bit[i]--;
                    }
                }
            };
            auto calculate = [&]() -> int {
                int res = 0;
                for (int i = 0; i < 32; i++) {
                    if (bit[i] == 0) {
                        res += (1 << i);
                    }
                }
                return res;
            };
            while (j < n) {
                add(nums[j]);
                while (i <= j && calculate() < x) {
                    subtract(nums[i]);
                    i++;
                }
                ans += (j - i + 1);
                j++;
            }
            return ans;
        };
        return f(k) - f(k + 1);
    }
};

