class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        i, j = 0, 0
        last = [-1] * 35
        cum = 0
        def process(idx):
            x = nums[idx]
            bi = 0
            while bi < 35:
                if x & (1 << bi) == 0:
                    last[bi] = idx
                bi += 1

        def missing(x):
            bi = 0
            ans = []
            while bi < 35:
                bit = 1 << bi
                if k & bit == 0 and (x & bit):
                    ans.append(bi)
                bi += 1
            return ans

        while i < len(nums) and j < len(nums):
            # print(i, j)
            if i < n and nums[i] & k != k:
                i += 1
                j = i
                continue
            if j < n and (nums[j] & k) != k:
                i, j = j+1, i
                continue
            process(j)
            # print(i, j, last)
            need = missing(nums[j])
            m = j
            for bi in need:
                m = min(m, last[bi])
            if m >= i:
                cum += m - i + 1
            j += 1
        return cum

