class Solution {
public:
    long long fun(vector<int> &a, int s, int e, int k) {
        // cout << s << ' ' << e << '\n';
        if (s > e) return 0ll;
        vector<queue<int>> bits(32);
        long long ans = 0;
        for (int i=0; i<32; i++) {
            for (int j=s; j<=e; ++j) {
                if (!(a[j] & (1<<i))) {
                    bits[i].push(j);
                }
            }
        }
        int i=s, mx = 0;
        bool flag = true;
        while (true) {
            for (int j=0; j<32; ++j) {
                if (k & (1<<j)) continue;
                if (bits[j].size() == 0) {
                    flag = false;
                    break;
                }
                mx = max(mx, bits[j].front());
            }
            if (!flag) break;
            ans += e-mx+1;
            for (int j=0; j<32; ++j) {
                if (!bits[j].empty() && bits[j].front() == i) bits[j].pop();
            }
            i++;
        }
        return ans;
    }

    long long countSubarrays(vector<int>& a, int k) {
        long long ans = 0, curr = 0, pi = 0;
        for (int i=0; i<a.size(); ++i) {
            if ((a[i] & k) == k) {
            } else {
                ans += fun(a, pi, i-1, k);
                pi = i+1;
            }
        }
        ans += fun(a, pi, a.size()-1, k);
        return ans;
    }
};

class Solution {
public:

    long long _and(vector<vector<int>> &dp,int l,int r){
        if(l>r)return (1ll<<31)-1;
        long long ans = 0;

        for(int j=0;j<31;j++){
            int ct = dp[r][j] - (l?dp[l-1][j]:0);
            if(ct == r-l+1)ans |= (1ll<<j);
        }
        return ans;
    }


    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();

        vector<vector<int>> dp(n,vector<int>(31));

        for(int i=0;i<n;i++){
            for(int j=0;j<31;j++){
                int is = (nums[i]>>j)&1;
                if(is)dp[i][j] = 1 + (i?dp[i-1][j]:0);
                else dp[i][j] = (i?dp[i-1][j]:0);
            }
        }



        long long pre[n];

        for(int i=0;i<n;i++){
            int l=0,r=i;
            int lower=-1;
            while(l<=r){
                int mid = (l+r)/2;
                int val = _and(dp,mid,i);
                if(val < k){
                    l=mid+1;
                }else if(val > k){
                    r=mid-1;
                }else{
                    r=mid-1;
                    lower=mid;
                }
            }
            l=0,r=i;
            int higher=-1;
            while(l<=r){
                int mid = (l+r)/2;
                int val = _and(dp,mid,i);
                if(val < k){
                    l=mid+1;
                }else if(val > k){
                    r=mid-1;
                }else{
                    l=mid+1;
                    higher=mid;
                }
            }
            // cout<<lower<<" "<<higher<<"\n";
            if(lower!=-1)pre[i] = higher-lower+1;
            else pre[i]=0;
        }

        long long ans=0;

        for(int val:pre){
            ans+=val;
        }

        return ans;


    }
};

