class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        N = sz(a);
        // 각 비트마다 on되어있는 자리 찾기
        // 1이면 다켜져야 하고, 0이면 누군가는 꺼져있어야 한다.
        // 켜져있어야 하는 제약조건은 구간이 커짐에 따라 충족이 힘들어지고
        // 꺼져있어야 하는 제약조건은 구간이 작아짐에 따라 충족이 힘들어진다.
        vector<vector<int>> cnt(31, vector<int>(N+1));
        for(int i = 0; i < N; i++) {
            for(int b = 0; b < 30; b++) {
                cnt[b][i+1] = cnt[b][i];
                if(a[i] >> b & 1) cnt[b][i+1]++;
            }
        }

        lint ret = 0;
        for(int r = 0; r < N; r++) {
            int L = 1, offL = r+1;

            bool impos = false, isOn = false, isOff = false;
            for(int b = 0; b < 30; b++) {
                if(!(k >> b & 1)) {
                    isOff = true;
                    int s = 1, e = r+1, cand = -1;
                    while(s <= e) {
                        int m = (s+e)/2;
                        if(cnt[b][r+1] - cnt[b][m-1] != r+1-m+1) {
                            cand = m;
                            s = m+1;
                        } else e = m-1;
                    }
                    // 꺼야하는데 어떻게 해도 끌 수가 없어
                    if(cand == -1) {
                        impos = true;
                        break;
                    }
                    // 최초로 0을 발견하는 지점이다.
                    // 얘보다는 L을 작거나 같게 설정해야 한다.
                    offL = min(offL, cand);
                } else {
                    isOn = true;
                    int s = 1, e = r+1, cand = -1;
                    while(s <= e) {
                        int m = (s+e)/2;
                        if(cnt[b][r+1] - cnt[b][m-1] == r+1-m+1) {
                            cand = m;
                            e = m-1;
                        } else s = m+1;
                    }
                    // 켜야 하는데 최대한 작게 만들어도 꺼져있어
                    if(cand == -1) {
                        impos = true;
                        break;
                    }
                    // 모두 1로 만들 수 있는 마지노선이다.
                    // 얘보다는 L을 크거나 같게 설정해야 한다.
                    L = max(L, cand);
                }
            }
            if(impos) continue;
            // L <= x <= offL
            if(offL < L) continue;
            if(!isOn) ret += offL;
            else if(!isOff) ret += r+1-L+1;
            else ret += (offL - L + 1);
        }
        return ret;
    }
};

