class Solution
{
public:
    long long countSubarrays(vector<int> &nums, int k)
    {
        ll n = (ll)nums.size();

        vector<vector<ll>> first0bit(n, vector<ll>(32));

        for (ll i = 0; i < 32; i++)
        {
            ll bit = nums[n - 1] & (1LL << i);

            if (bit)
            {
                first0bit[n - 1][i] = -1;
            }

            else
            {
                first0bit[n - 1][i] = n - 1;
            }
        }

        for (ll i = n - 2; i >= 0; i--)
        {
            for (ll j = 0; j < 32; j++)
            {
                ll bit = nums[i] & (1LL << j);

                if (bit)
                {
                    first0bit[i][j] = first0bit[i + 1][j];
                }

                else
                {
                    first0bit[i][j] = i;
                }
            }
        }

        ll ans = 0;

        for (ll i = 0; i < n; i++)
        {
            ll l = i, r = n - 1;
            bool ok = true;

            for (ll j = 0; j < 32; j++)
            {
                ll bit1 = nums[i] & (1LL << j);
                ll bit2 = k & (1LL << j);

                if (bit1 == 0 && bit2 != 0)
                {
                    ok = false;
                    break;
                }

                if (bit2)
                {
                    if (first0bit[i][j] != -1)
                    {
                        r = min(r, first0bit[i][j] - 1);
                    }
                }

                else
                {
                    if (first0bit[i][j] == -1)
                    {
                        ok = false;
                        break;
                    }

                    l = max(l, first0bit[i][j]);
                }
            }

            if (ok && r - l + 1 > 0)
            {
                ans += r - l + 1;
            }
        }

        return ans;
    }
};

