class Solution {
public:
    long long countSubarrays(vector<int>& numbers, int target) {
     int size = numbers.size();
    long long result_count = 0;

    unordered_map<long long, long long> previous_results;

    for (int idx = 0; idx < size; ++idx) {
        unordered_map<long long, long long> current_results; 

        if (numbers[idx] == target) {
            ++result_count;
        }
        current_results[numbers[idx]] = 1;

        for (auto& [value, frequency] : previous_results) {
            long long new_and_result = value & numbers[idx];
            if (new_and_result == target) {
                result_count += frequency;
            }
            current_results[new_and_result] += frequency;
        }

        previous_results = current_results;
    }

    return result_count;    
    }
};

