    type pair struct {a, cnt int}
	and := []pair{} 
	for _, x := range nums {
        and = append(and, pair{x, 1})
		and[0].a &= x
		j := 0
		for _, p := range and[1:] {
			p.a &= x
			if and[j].a == p.a {
				and[j].cnt += p.cnt
			} else {
				j++
				and[j] = p
			}
		}
		and = and[:j+1] 
        for _, p := range and {
            if p.a == k {
                ans += p.cnt
            }
        }

	}

    return int64(ans)
}

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        long long ans = 0;
        map<int,long long> mp;
        map<int,long long> mp2;
        for(int i=0;i<n;i++){
            for(const auto&[key,val] : mp){
                int res = key&nums[i];
                if(res==k) ans+=val;
                if(res>=k){
                    mp2[res] += val;
                }
            }
            mp = mp2;
            mp2.clear();
            if(nums[i] == k) ans++;
            if(nums[i] >= k) mp[nums[i]]++;
            else{
                mp.clear();
            }
        }
        return ans;
    }
};

class Solution {
    fun countSubarrays(numbers: IntArray, target: Int): Long {
        val n = numbers.size
        var count = 0L

        val prevResults = mutableMapOf<Long, Long>()

        for (i in numbers.indices) {
            val currResults = mutableMapOf<Long, Long>()

            if (numbers[i] == target) {
                count++
            }
            currResults[numbers[i].toLong()] = 1

            for ((value, frequency) in prevResults) {
                val newAndResult = value and numbers[i].toLong()
                if (newAndResult == target.toLong()) {
                    count += frequency
                }
                currResults[newAndResult] = currResults.getOrDefault(newAndResult, 0L) + frequency
            }

            prevResults.clear()
            prevResults.putAll(currResults)
        }

        return count
    }
}

class Solution {
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        long count = 0;
        Map<Long, Long> prev = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            Map<Long, Long> curr = new HashMap<>();
            if (nums[i] == k) {
                ++count;
            }
            curr.put((long) nums[i], 1L);

            for (Map.Entry<Long, Long> entry : prev.entrySet()) {
                long v = entry.getKey();
                long f = entry.getValue();
                long r = v & nums[i];
                if (r == k) {
                    count += f;
                }
                curr.put(r, curr.getOrDefault(r, 0L) + f);
            }

            prev = curr;
        }

        return count;
    }
}

