typedef long long ll;

class SegmentTree
{

private:

    vector<ll> seg;

public:

    SegmentTree(ll n)
    {
        seg.resize(4*n+1);
    }

    void build(ll ind,ll lo,ll hi,vector<ll> &a)
    {
        if(lo==hi)
        {
            seg[ind]=a[lo];
            return;
        }
        ll mid=lo+(hi-lo)/2;
        build(2*ind+1,lo,mid,a);
        build(2*ind+2,mid+1,hi,a);
        seg[ind]=(seg[2*ind+1]&seg[2*ind+2]);
    }

    ll query(ll ind,ll lo,ll hi,ll l,ll r)
    {
        if(l>hi||lo>r)
        {
            return (1LL<<31)-1;
        }
        if(l<=lo&&hi<=r)
        {
            return seg[ind];
        }
        ll mid=lo+(hi-lo)/2;
        ll left=query(2*ind+1,lo,mid,l,r),right=query(2*ind+2,mid+1,hi,l,r);
        return (left&right);
    }

};

class Solution
{
public:
ll countSubarrays(vector<int> &nums,int K)
{
    ll k=(ll)K,n=(ll)nums.size(),ans=0;
    vector<ll> a;
    for(auto &v:nums)
    {
        a.push_back((ll)v);
    }
    SegmentTree st(n);
    st.build(0,0,n-1,a);
    for(ll i=0;i<n;++i)
    {
        ll idx1=-1,idx2=-1,lo=i,hi=n-1;
        bool found=false;
        while(hi>=lo)   // 1st idx <= k
        {
            ll mid=lo+(hi-lo)/2;
            ll x=st.query(0,0,n-1,i,mid);
            if(x==k)
            {
                found=true;
            }
            if(x<=k)
            {
                idx1=mid;
                hi=mid-1;
            }
            else
            {
                lo=mid+1;
            }
        }
        lo=i;
        hi=n-1;
        while(hi>=lo)   // last idx >= k
        {
            ll mid=lo+(hi-lo)/2;
            ll x=st.query(0,0,n-1,i,mid);
            if(x>=k)
            {
                idx2=mid;
                lo=mid+1;
            }
            else
            {
                hi=mid-1;
            }
        }
        if(found)
        {
            ans+=(idx2-idx1+1);
        }
    }
    return ans;
}
};

