class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        vector<vector<int>> bi(31, vector<int>(n, 0));
        vector<vector<int>> next_zero(31, vector<int>(n, 0));
        for (int i=0; i < n; i++) {
            for (int j=0; j < 31; j++) {
                bi[j][i] = nums[i]&(1<<j);
            }
        }

        for (int j=0; j < 31; j++) {
            for (int i=n-1; i >= 0; i--) {
                if (i == n-1) {
                    if (bi[j][i] > 0) {
                        next_zero[j][i] = n;
                    } else {
                        next_zero[j][i] = i;
                    }
                } else {
                    if (bi[j][i] > 0) {
                        next_zero[j][i] = next_zero[j][i+1];
                    } else {
                        next_zero[j][i] = i;
                    }
                }
            }
        }

        long long ans = 0;
        for (int i=0; i < n; i++) {
            int lb = i;
            int ub = n;
            for (int j=0; j < 31; j++) {
                if (k&(1<<j)) {
                    ub = min(ub, next_zero[j][i]);
                } else {
                    lb = max(lb, next_zero[j][i]);
                }
            }
            // cout<<i<<" "<<lb<<" "<<ub<<endl;
            ans += max(0, ub-lb);
        }
        return ans;
    }
};

