class Solution {
public:
    int countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        int count = 0;
        int current_and = 0;
        int left = 0;

        for (int right = 0; right < n; ++right) {
            current_and &= nums[right];

            // Adjust left pointer to maintain the condition
            while (current_and > k) {
                current_and &= ~nums[left++];
            }

            // If current_and equals k, count subarrays
            if (current_and == k) {
                int subarrays = right - left + 1;
                count += subarrays;
            }
        }

        return count;
    }
};

