        SGTree seg(n+5);
        seg.build(0,0,n-1,nums);
        ll cnt=0;
        for(int i=0; i<n; i++) {
            ll l=i,r=n-1;
            ll ans=-1;

            while(l<=r) {
                ll mid=(l+r)/2;

                ll val=seg.query(0,0,n-1,i,mid);

                if(val>k) {
