class Segment_Tree 
{
private:
    vector<int> seg;

public:
    Segment_Tree (int n) {
        seg.resize(4 * n + 5);
    }

    void build (vector<int>& arr, int low, int high, int i)
    {
        if (low == high)
        {
            seg[i] = arr[low];
            return;
        }

        int mid = (low + high) >> 1;
        build(arr, low, mid, 2 * i + 1);
        build(arr, mid + 1, high, 2 * i + 2);

        seg[i] = (seg[2 * i + 1] & seg[2 * i + 2]);
    }

    int query (int i, int low, int high, int l, int r)
    {
        if (r < low || l > high || r < l)
            return ((1LL << 31) - 1);

        if (l <= low && r >= high)
            return seg[i];

        int mid = (low + high) >> 1;
        int left = query(2 * i + 1, low, mid, l, r);
        int right = query(2 * i + 2, mid + 1, high, l, r);

        return (left & right);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& arr, int k) {
        int i = 0, j = 0, n = arr.size();
        long long total = 0;

        Segment_Tree st(n);
        st.build(arr, 0, n - 1, 0);

        for (int i = 0; i < n; i++)
        {
            int low = i, high = n - 1, ans = -1;

            while (low <= high)
            {
                int mid = (low + high) / 2;

                if (st.query(0, 0, n - 1, i, mid) <= k)
                    ans = mid, high = mid - 1;
                else
                    low = mid + 1;
            }

            if (ans == -1 || st.query(0, 0, n - 1, i, ans) != k)
                continue;

            low = i, high = n - 1;
            int ans1 = ans;

            while (low <= high)
            {
                int mid = (low + high) / 2;

                if (st.query(0, 0, n - 1, i, mid) >= k)
                    ans = mid, low = mid + 1;
                else
                    high = mid - 1;
            }

            total += ans - ans1 + 1;
        }

        return total;
    }
};

