#define MAXBIT 30
#define MAXN 100000
class Solution {
public:

    int cumul[MAXBIT+1][MAXN+2];


    int GetAnd(int i,int j,const vector<int>& nums) {
        // if (i > j) return (1ll<<30)-1;
        // int ret = (1ll<<30)-1;
        // for(int k=i;k<=j;k++) {
        //     ret &= nums[k];
        // }
        // return ret;
        int ret = (1ll<<MAXBIT)-1;
        for(int b=0;b<MAXBIT;b++) {
            if (cumul[b][j]-(i?cumul[b][i-1]:0)<j-i+1) ret^=(1ll<<b); 
        }
        return ret;
    }

    int GetSmallest(int i, const vector<int>& nums, int k) {
        int n=nums.size();

        int low=i;
        int high=n-1;
        while(low<high) {
            int mid=(low+high)/2;
            if (GetAnd(i,mid,nums)>k) {
                low=mid+1;
            } else {
                high=mid;
            }
        }
        return low;

    }

    int GetLargest(int i, const vector<int>& nums, int k) {
        int n=nums.size();

        int low=i-1;
        int high=n-1;
        while(low<high) {
            int mid=(1+low+high)/2;
            if (GetAnd(i,mid,nums)>=k) {
                low=mid;
            } else {
                high=mid-1;
            }
        }
        return low;
    }

    long long countSubarrays(vector<int>& nums, int k) 
    {

        int n=nums.size();

        for(int b=0;b<=MAXBIT;b++) {
            for(int i=0;i<n;i++) {
                cumul[b][i]=((nums[i]>>b)&1);
                if (i) cumul[b][i]+=cumul[b][i-1];
            }
        }

        long long ans=0;
        for(int i=0;i<n;i++) {
            // smallest index such that and is <= k
            // largest index such that and is >= k

            int low=GetSmallest(i,nums,k);
            int high=GetLargest(i,nums,k);
            if (low <= high && GetAnd(i,low,nums)==k)  ans += high-low+1;

        }
        return ans;

    }
};

class Solution {
public:

    bool check(int y, int x) {
        while (x) {
            if ((x & 1))
                if (!(y & 1)) return 0;
            x >>= 1, y >>= 1;
        }
        return 1;
    }

    long long countSubarrays(vector<int>& nums, int K) {
        long long ans = 0, x = 0;
        vector<int> v(31);

        for (int i = 0; i < 31; i++)
            if (!(K & (1 << i)))
                v[i] = 1, x++;

        for (int s = 0; s < nums.size(); s++) {
            int e = s;
            while (e < nums.size() && check(nums[e], K)) e++;
            int i = s, j = s, cnt = 0;
            vector<int> cur(31);
            while (i < e) {
                while (j < e && cnt < x) {
                    for (int k = 0; k < 31; k++)
                        if (!(nums[j] & (1 << k)) && v[k]) {
                            if (!cur[k]) cnt++;
                            cur[k]++;
                        }
                    j++;
                }
                // cout << j << " " << e;
                if (cnt == x)
                    ans += e - j + 1;
                for (int k = 0; k < 31; k++)
                    if (!(nums[i] & (1 << k)) && v[k]) {
                        if (1 == cur[k]) cnt--;
                        cur[k]--;
                    }
                i++;
            }
            s = max(s, e - 1);
        }
        return ans;
    }
};

