class Solution {
public:
    class minST
    {
    private:
        int k;
        vector<vector<int>> ds;
    public:
        minST(vector<int> &arr)
        {
            int n = arr.size();
            this->k = log2(n);
            ds.resize(k + 1, vector<int>(n, 0));
            ds[0] = arr;
            for(int i = 1; i <= k; i++)
                for(int j = 0; j + (1 << i) <= n; j++)
                    ds[i][j] = ds[i - 1][j] & ds[i - 1][j + (1 << (i - 1))];
        }

        int query(int l, int r)
        {
            int lg = log2(r - l + 1);
            return ds[lg][l] & ds[lg][(r - (1 << lg)) + 1];
        }
    };
    long long countSubarrays(vector<int>& nums, int k) {
        minST st(nums);
        int n = nums.size();
        long long ans = 0;
        for(int i = 0; i < n; i++) {
            int startInd = -1;
            int endInd = -1;

            int s = 0;
            int e = i;
            while(s <= e) {
                int mid = (s + e) / 2;
                if(st.query(mid, i) >= k) 
                    startInd = mid, e = mid - 1;
                else 
                    s = mid + 1;
            }

            s = 0;
            e = i;
            while(s <= e) {
                int mid = (s + e) / 2;
                if(st.query(mid, i) <= k) 
                    endInd = mid, s = mid + 1;
                else 
                    e = mid - 1;
            }

            if(endInd != -1 && startInd != -1)
                ans += (endInd - startInd) + 1;
        }
        return ans;
    }
};

