    long long countSubarrays(vector<int>& a, int k) {
        int n=a.size();
        int pre[n][32];
        int pre_one[n][32];
        int pre_zero[n][32];
        memset(pre,0,sizeof(pre));
        memset(pre_one,0,sizeof(pre));
        memset(pre_zero,0,sizeof(pre));
        for(int i=0;i<n;i++)
        {
            int no=a[i];
            int j=0;
            while(no)
            {
                int bit=(no&1);
                pre[i][j]=bit;
                no>>=1;
                j++;
                //cout<<j<<endl;
            }
        }
        for(int j=0;j<32;j++)
        {
            int last=-1;
            for(int i=0;i<n;i++)
            {
                if(pre[i][j]==0)last=i;
                pre_zero[i][j]=last;
            }
        }
        for(int j=0;j<32;j++)
        {
            int last=-1;
            int f=0;
            for(int i=0;i<n;i++)
            {
                if(pre[i][j]==1)
                {
                    if(f==0)
                    {
                        last=i;
                        pre_one[i][j]=last;
                        f=1;
                    }
                    else
                    {
                        pre_one[i][j]=last;
                    }
                }
                else pre_one[i][j]=-1,f=0;
            }
        }
        int temp[32]{0};
        int idx=0;
        while(k)
        {
            int bit=(k&1);
            temp[idx++]=bit;
            k>>=1;
        }
        long long ans=0;
        for(int i=0;i<n;i++)
        {
            bool flag=true;
            int mn=1e9,mx=-1e9;
            for(int j=0;j<32;j++)
            {
                if(temp[j]==0)
                {
                    int last=pre_zero[i][j];
                    if(last==-1)
                    {
                        flag=false;
                        break;
                    }
                    mn=min(last,mn);
                }
                else
                {
                    int last=pre_one[i][j];
                    if(last==-1)
                    {
                        flag=false;
                        break;
                    }
                    mx=max(last,mx);
                }
            }
            if(flag==false)continue;
            if(mn==1e9)
            {
                ans+=(i-mx+1);
                continue;
            }
            if(mx==-1e9)
            {
                ans+=(mn+1);
                continue;
            }
            if(mx>mn)continue;
            ans+=(mn-mx+1);
        }
        return ans;
    }
};

class Solution {
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        long totalSubarraysCnt = 0;
        Map<Long, Long> prevResults = new HashMap<>();

        for (int idx = 0; idx < n; ++idx) {
            Map<Long, Long> currResults = new HashMap<>();

            if (nums[idx] == k) {
                ++totalSubarraysCnt;
            }

            currResults.put((long) nums[idx], 1L);

            for (Map.Entry<Long, Long> entry : prevResults.entrySet()) {
                long val = entry.getKey();
                long freq = entry.getValue();

                long newAndResult = val & nums[idx];

                if (newAndResult == k) {
                    totalSubarraysCnt += freq;
                }

                currResults.put(newAndResult, currResults.getOrDefault(newAndResult, 0L) + freq);
            }

            prevResults = currResults;
        }

        return totalSubarraysCnt;
    }
}

class Solution {
public:
    void addNum(int n, vector<int> &bits){
        for(int i=0; i<32; ++i){
            if((n >> i)&1) bits[i]++;
        }
    }
    void remNum(int n, vector<int> &bits){
        for(int i=0; i<32; ++i){
            if((n >> i)&1) bits[i]--;
        }
    }
    int val(vector<int> &bits, int sz){
        int ans = 0;
        for(int i=0; i<32; ++i){
            int sets = bits[i];
            if(sets == sz) ans += 1 << i;
        }
        return ans;
    }

    long long f(vector<int>& nums, int k){
        vector<int> bits(32);

        int n = nums.size();
        int j = 0;
        long long ans = 0;
        for(int i=0; i<n; ++i){
            addNum(nums[i], bits);
            int x = val(bits, i - j + 1 );
            while(j <= i && x < k){
                remNum(nums[j], bits);
                j++;
                x = val(bits,i-j+1);
            }
            // x = val(nums[i], i - j + 1);
            if(j<=i &&  val(bits, i - j + 1) >= k) ans += i - j + 1;
        }
        return ans;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        long long a = f(nums, k);
        long long b = f(nums, k+1);
        return a - b;
    }
};

