class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        ci = None
        r = 0
        s = 0
        j = None
        ss = None
        for i, n in enumerate(nums):
            if n & k == k:
                if ci is not None:
                    s = s & n
                    if s == k:
                        r += i - ci
                        if j is None:
                            j = i - 1
                            ss = n
                            while j >= 0 and ss & nums[j] != k:
                                ss = ss & nums[j]
                                j -= 1
                            r -= i - j - 1
                        # j = None
                        else:
                            if n & ss != k:
                                ss = ss & n
                                r -= i - j - 1
                            else:
                                j = i - 1
                                ss = n
                                while j >= 0 and ss & nums[j] != k:
                                    ss = ss & nums[j]
                                    j -= 1
                                r -= i - j - 1

                    if n == k:
                        r += 1
                        j = None
                else:
                    ci = i
                    s = n
                    if n == k:
                        r += 1
                    j = None
            else:
                ci = None
                s = 0
                j = None
        return r

