class Solution {
public:
long long int query(long long int ind,long long int low,long long int high,vector<long long int>&seg,long long int l,long long int r)
{
    if(l>high||r<low)return INT_MAX;
    if(l<=low&&r>=high)return seg[ind];

    long long int mid=(low+high)/2;
    long long int left=query(2*ind+1,low,mid,seg,l,r);
    long long int right=query(2*ind+2,mid+1,high,seg,l,r);
    return left&right;
}

void build(long long int ind,long long int low,long long int high,vector< int>&arr,vector<long long int>&seg)
{
    if(low==high)
    {
        seg[ind]=arr[low];
        return;
    }

    long long int mid=(low+high)/2;
    build(2*ind+1,low,mid,arr,seg);
    build(2*ind+2,mid+1,high,arr,seg);
    seg[ind]=seg[2*ind+1]&seg[2*ind+2];
}


long long s(vector<int> &nums,long long k,vector<long long> &seg){
        long long n=nums.size();
        long long cnt= 0;
        for(long long i=0;i<n;i++){
            long long low = i;
            long long high = n-1;
            long long ans=-1;
            while(low<=high){
                long long mid = low + (high - low)/2;
                long long qu = query(0,0,n-1,seg,i,mid);
                if(qu<=k){
                    ans = mid;
                    high = mid - 1;
                }
                else{
                    low = mid + 1;   
                }
            }
            if(ans!=-1){
                cnt+=(n-ans);
            }
        }
    return cnt;
}
    long long countSubarrays(vector<int>& nums, int k) {
        long long n=nums.size();
        vector<long long> seg(4*n+10,-1);
        build(0,0,n-1,nums,seg);
        long long t = s(nums,k,seg);
