class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        ll sum=0;
        map<ll,ll> m;
        for(ll i=0;i<n;i++){
            ll temp = 0;
            ll cur = a[i];
            map<ll,ll> mp;
            mp[cur]++;
            for(auto it:m){
                ll f = it.first;
                ll s = it.second;
                ll nw = (f&cur);
                if(nw==k){
                    temp+=s;
                }
                mp[nw]+=s;
            }
            if(cur==k){
                sum++;
            }
            sum = (sum + temp);
            m = mp;
        }
        return sum;
    }
};

