class Solution {
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        long count = 0;
        Map<Long, Long> prevResults = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            Map<Long, Long> currResults = new HashMap<>();
            if (nums[i] == k) {
                ++count;
            }
            currResults.put((long) nums[i], 1L);
            for (Map.Entry<Long, Long> entry : prevResults.entrySet()) {
                long val = entry.getKey();
                long freq = entry.getValue();
                long newAndResult = val & nums[i];
                if (newAndResult == k) {
                    count += freq;
                }
                currResults.put(newAndResult, currResults.getOrDefault(newAndResult, 0L) + freq);
            }
            prevResults = currResults;
        }
        return count;
    }
}

class Solution {
public:
    int isPossible(vector<vector<int>>& pre, int st, int en){
        int x = 0;
        for(int i=29;i>=0;i--){
            int diff = pre[en+1][i] - pre[st][i];
            if(diff == (en-st+1)){
                x|= (1<<i);
            }
        }

        return x;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        long long ans = 0;
        int n = nums.size();
        vector<vector<int>> pre(n+1, vector<int>(30, 0));
        for(int i=0;i<n;i++){
            for(int j=29;j>=0;j--){
                pre[i+1][j]+= pre[i][j];
                if(nums[i]&(1<<j)){
                    pre[i+1][j]++;
                }
                else{

                }
            }
        }

        for(int i=0;i<n;i++){
            if(nums[i]<k) continue;
            int l=i, r=n-1, m;

            while(l<=r){
                int m = (l+r) >> 1;
                int x = isPossible(pre, i, m);
                if(x > k){
                    l = m+1;
                }
                else r=m-1;
            }
            int st = l;
            if(st == n) continue;
            int v1 = isPossible(pre, i, st);
            if(v1 != k) continue;
            l=i, r=n-1, m;
            while(l<=r){
                int m = (l+r) >> 1;
                int x = isPossible(pre, i, m);
                if(x >= k){
                    l = m+1;
                }
                else r=m-1;
            }

            ans+= (l-st);
        }

        return ans;
    }
};
